/* GENERATED by scripts/build-atlas-data.cjs from atlas/graph/ — do not hand-edit. */
/* Main-atlas questions. Load after data.js, before app.js; assigns into window.ATLAS. */
(() => {
  'use strict';
  window.ATLAS.questions = [
    {"id":"q-averaging-leveling-0","question":{"zh":"平均数为什么是总数除以个数？","en":"Why is the mean the total divided by the count?"},"chain":["averaging-leveling","bar-charts"],"target":{"node":"averaging-leveling","href":"../averaging-leveling/#step2"},"prompts":[{"node":"averaging-leveling","ask":{"zh":"把几杯不一样多的水倒匀，最后每杯水位一样高——倒匀前后，水的总量变了吗？","en":"If you pour several uneven cups until every cup is level, does the total amount of water change?"}},{"node":"bar-charts","ask":{"zh":"在条形图上画一条平均线，高出这条线的部分和低于这条线的部分有什么关系？","en":"On a bar chart, how does the part above the mean line relate to the part below it?"}}],"reveal":{"zh":"总量不变，倒匀后每杯都是总量÷杯数，所以平均数就是总数除以个数；图上的平均线正好让高出部分补上不足部分。","en":"The total never changes, and after levelling every cup holds total ÷ cups — that is why the mean is the total divided by the count, and the mean line on a chart is exactly where the excess fills the shortfall."},"source":"../averaging-leveling/#step2","lesson":"averaging-leveling","stage":"primary","group":"measurement"},
    {"id":"q-bar-charts-0","question":{"zh":"平均数在图上到底是什么？","en":"What is the mean on a chart?"},"chain":["bar-charts","probability"],"target":{"node":"bar-charts","href":"../bar-charts/#step3"},"prompts":[{"node":"bar-charts","ask":{"zh":"柱子有高有低，平均线画在哪里，才会让高出部分刚好补平不足部分？","en":"With bars of different heights, where must the mean line sit so the excess exactly fills the shortfall?"}},{"node":"probability","ask":{"zh":"如果再来一个新数据，它落在平均线上面，会把平均数往上拉还是往下拉？","en":"If one new value lands above the mean line, does it pull the mean up or down?"}}],"reveal":{"zh":"平均线就是让高出与不足互相抵消的那条线；新数据高于平均线会把平均数往上拉，低于则往下拉。","en":"The mean line is the level where excess and shortfall cancel out; a new value above it pulls the mean up, below it pulls it down."},"source":"../bar-charts/#step3","lesson":"bar-charts","stage":"primary","group":"measurement"},
    {"id":"q-chicken-rabbit-0","question":{"zh":"不用方程怎样解鸡兔同笼？","en":"How do you solve chickens-and-rabbits without algebra?"},"chain":["chicken-rabbit","slope"],"target":{"node":"chicken-rabbit","href":"../chicken-rabbit/#step2"},"prompts":[{"node":"chicken-rabbit","ask":{"zh":"先假设全是鸡，算出来的脚数和实际脚数差多少？这个差额从哪里来？","en":"Assume they are all chickens first — how many feet short are you, and where does that gap come from?"}},{"node":"slope","ask":{"zh":"每把一只鸡换成一只兔，脚数增加几只？差额除以这个数，得到的是什么？","en":"Each time you swap one chicken for one rabbit, how many more feet appear? What does the gap divided by that number give you?"}}],"reveal":{"zh":"差额来自兔子比鸡多的脚；每换一只多 2 只脚，所以差额÷2 就是兔子的只数，剩下的就是鸡。","en":"The gap comes from rabbits having more feet than chickens; each swap adds 2 feet, so gap ÷ 2 is the number of rabbits and the rest are chickens."},"source":"../chicken-rabbit/#step2","lesson":"chicken-rabbit","stage":"primary","group":"math"},
    {"id":"q-circle-intro-0","question":{"zh":"π 到底是怎么来的？","en":"Where does π actually come from?"},"chain":["circle-intro","unit-circle"],"target":{"node":"circle-intro","href":"../circle-intro/#step3"},"prompts":[{"node":"circle-intro","ask":{"zh":"量几个大小不同的圆，周长除以直径，结果有什么共同点？","en":"Measure circles of different sizes and divide each circumference by its diameter — what do the answers have in common?"}},{"node":"unit-circle","ask":{"zh":"半径是 1 的圆，周长是多少？这个结果和 π 有什么关系？","en":"For a circle of radius 1, what is the circumference, and how does that relate to π?"}}],"reveal":{"zh":"不管圆多大，周长÷直径总是一个固定数，就是 π；半径 1 的圆周长正好是 2π。","en":"No matter the size, circumference ÷ diameter is always the same constant, π; a radius-1 circle has circumference 2π."},"source":"../circle-intro/#step3","lesson":"circle-intro","stage":"primary","group":"math"},
    {"id":"q-clock-angles-0","question":{"zh":"两根针什么时候重合？","en":"When do the clock hands overlap?"},"chain":["clock-angles","unit-circle"],"target":{"node":"clock-angles","href":"../clock-angles/#step1"},"prompts":[{"node":"clock-angles","ask":{"zh":"分针每分钟走 6°，时针每分钟走 0.5°，分针每分钟追上时针多少度？","en":"The minute hand moves 6° per minute and the hour hand 0.5° — how many degrees does the minute hand gain each minute?"}},{"node":"unit-circle","ask":{"zh":"把一圈看成 360°，分针要追上多少度，才会再次和时针重合？","en":"Thinking of a full turn as 360°, how many degrees must the minute hand gain to catch the hour hand again?"}}],"reveal":{"zh":"每分钟追上 5.5°，追满一圈 360° 需要 360÷5.5 ≈ 65.5 分钟，所以大约每 1 小时 5 分半重合一次。","en":"It gains 5.5° per minute, so catching up a full 360° takes 360 ÷ 5.5 ≈ 65.5 minutes — the hands overlap about every 1 hour 5½ minutes."},"source":"../clock-angles/#step1","lesson":"clock-angles","stage":"primary","group":"measurement"},
    {"id":"q-float-sink-0","question":{"zh":"为什么橡皮泥捏成船就能浮？","en":"Why does plasticine float once shaped into a boat?"},"chain":["float-sink","net-force"],"target":{"node":"float-sink","href":"../float-sink/#step1"},"prompts":[{"node":"float-sink","ask":{"zh":"橡皮泥捏成船以后，它排开的水是变多了还是变少了？排开的水越重，浮力怎样变？","en":"Once the plasticine is shaped into a boat, does it displace more water or less? And the heavier the displaced water, the stronger or weaker the buoyant force?"}},{"node":"net-force","ask":{"zh":"船浮在水面不动时，浮力和重力哪个大？两者相等意味着什么？","en":"When the boat floats still on the water, is the buoyant force bigger than gravity or equal to it? What does that equality mean?"}}],"reveal":{"zh":"捏成船排开的水变多了，浮力等于排开水的重量，变大到足以托住橡皮泥；浮起来静止时浮力与重力相等。","en":"Shaped into a boat it displaces more water, and buoyant force equals the weight of that water — now large enough to hold the plasticine up; floating still means buoyant force equals gravity."},"source":"../float-sink/#step1","lesson":"float-sink","stage":"primary","group":"waves"},
    {"id":"q-intervals-fences-0","question":{"zh":"为什么总是差一？","en":"Why is it always off by one?"},"chain":["intervals-fences","patterns-sequences"],"target":{"node":"intervals-fences","href":"../intervals-fences/#step2"},"prompts":[{"node":"intervals-fences","ask":{"zh":"一排树两端都种，棵数比段数多几？如果两端都不种呢？","en":"Plant a row of trees with both ends planted — how many more trees than gaps? What if neither end is planted?"}},{"node":"patterns-sequences","ask":{"zh":"每增加一段，棵数增加几棵？这个规律怎样写成第 n 段的公式？","en":"Each extra gap adds how many trees? How would you write that as a rule for the nth gap?"}}],"reveal":{"zh":"两端都种多 1 棵，只种一端不多不少，两端都不种少 1 棵；差一来自“段数”和“点数”数的不是同一样东西。","en":"Both ends planted gives one extra tree, one end planted gives equal counts, neither end planted gives one fewer — the off-by-one comes from counting gaps versus counting posts, two different things."},"source":"../intervals-fences/#step2","lesson":"intervals-fences","stage":"primary","group":"math"},
    {"id":"q-magnets-0","question":{"zh":"看不见的磁场怎样被画出来？","en":"How do we draw an invisible magnetic field?"},"chain":["magnets","vectors"],"target":{"node":"magnets","href":"../magnets/#step2"},"prompts":[{"node":"magnets","ask":{"zh":"在磁铁周围撒铁屑，铁屑排成的线从哪极出来、进哪极？哪里排得最密？","en":"Scatter iron filings around a magnet — which pole do the lines leave, which do they enter, and where are they densest?"}},{"node":"vectors","ask":{"zh":"磁感线上的箭头表示什么方向？线上某一点的箭头方向就是那一点磁场的什么？","en":"What direction does an arrow on a field line show? At any point, the arrow's direction is the direction of what?"}}],"reveal":{"zh":"铁屑连成的磁感线从 N 极出、进 S 极，越靠近磁极越密；线上的箭头就是该点磁场的方向。","en":"The filings trace field lines leaving N and entering S, densest near the poles; the arrow on a line at any point is the direction of the field there."},"source":"../magnets/#step2","lesson":"magnets","stage":"primary","group":"circuits"},
    {"id":"q-moon-phases-0","question":{"zh":"为什么月亮会有圆缺？","en":"Why does the Moon change shape?"},"chain":["moon-phases","unit-circle"],"target":{"node":"moon-phases","href":"../moon-phases/#step1"},"prompts":[{"node":"moon-phases","ask":{"zh":"月亮永远亮半边，为什么我们有时只看到一小部分亮面？","en":"The Moon is always half lit — so why do we sometimes see only a sliver of bright face?"}},{"node":"unit-circle","ask":{"zh":"把月亮绕地球的位置想成圆上的一个角，看到的亮面比例 (1 − cos θ)/2 在 θ 很小和 θ = 180° 时各是多少？","en":"Think of the Moon's position as an angle on a circle — what is the lit fraction (1 − cos θ)/2 when θ is tiny, and when θ = 180°?"}}],"reveal":{"zh":"亮面比例由月亮相对太阳的位置角决定，θ 从 0 变到 180°，亮面从 0 变到全部，大约 29.5 天一个周期。","en":"The lit fraction follows the Moon's angle relative to the Sun: as θ goes from 0 to 180°, the lit face grows from none to full, over a cycle of about 29.5 days."},"source":"../moon-phases/#step1","lesson":"moon-phases","stage":"primary","group":"earth"},
    {"id":"q-patterns-sequences-0","question":{"zh":"为什么数得出前几项就能写出第 n 项？","en":"Why can counting a few terms give a rule for the nth?"},"chain":["patterns-sequences","slope"],"target":{"node":"patterns-sequences","href":"../patterns-sequences/#step2"},"prompts":[{"node":"patterns-sequences","ask":{"zh":"火柴棒链每加一个图形，总数增加几根？这个增量变不变？","en":"Each new figure in the matchstick chain adds how many sticks? Does that step stay the same?"}},{"node":"slope","ask":{"zh":"总数 = 增量 × n + 起头，这里的“增量”在图上像不像一条直线的斜率？","en":"In total = step × n + starter, does the \"step\" behave like the slope of a straight line?"}}],"reveal":{"zh":"增量不变时，每一项都在前一项上加同一个数，所以总数 = 增量 × n + 起头，不用画到第 100 个也能算出来。","en":"With a constant step, each term just adds the same number to the previous one, so total = step × n + starter — the 100th term needs no drawing."},"source":"../patterns-sequences/#step2","lesson":"patterns-sequences","stage":"primary","group":"math"},
    {"id":"q-place-value-0","question":{"zh":"乘 10 为什么是数字左移？","en":"Why does times 10 slide the digits left?"},"chain":["place-value","patterns-sequences"],"target":{"node":"place-value","href":"../place-value/#step2"},"prompts":[{"node":"place-value","ask":{"zh":"在计数器上，一个珠子从个位移到十位，它表示的数变成几倍？","en":"On a counting frame, a bead moved from the ones place to the tens place is worth how many times more?"}},{"node":"patterns-sequences","ask":{"zh":"连续左移两位、三位，分别是乘几？这个规律和找规律里的“每次加同一个数”有什么不同？","en":"Sliding two places left, then three — multiply by what each time? How is this different from a pattern where you add the same number each step?"}}],"reveal":{"zh":"每左移一位大 10 倍，所以乘 10 就是全体数字左移一位，末尾补 0 占位；这是乘法规律，不是加法规律。","en":"Each place left is worth 10 times more, so times 10 slides every digit one place left with a 0 holding the end place — a multiplicative pattern, not an additive one."},"source":"../place-value/#step2","lesson":"place-value","stage":"primary","group":"math"},
    {"id":"q-simple-circuits-0","question":{"zh":"为什么短路会危险？","en":"Why is a short circuit dangerous?"},"chain":["simple-circuits","power"],"target":{"node":"simple-circuits","href":"../simple-circuits/#step3"},"prompts":[{"node":"simple-circuits","ask":{"zh":"只有闭合的回路才有电流；如果用一根导线直接连电池两端，电流还经过灯泡吗？","en":"Current needs a closed loop — if a wire connects the battery's two ends directly, does the current still go through the bulb?"}},{"node":"power","ask":{"zh":"同一节电池，电流变大很多倍，导线发热会怎样变？","en":"With the same battery, if the current grows many times larger, what happens to the wire's heating?"}}],"reveal":{"zh":"短路绕过了灯泡，回路电阻极小，电流远大于正常值，导线急剧发热，容易烧坏甚至起火。","en":"A short circuit bypasses the bulb, so the loop's resistance is tiny and the current is far above normal — the wire heats up fast and can burn or catch fire."},"source":"../simple-circuits/#step3","lesson":"simple-circuits","stage":"primary","group":"circuits"},
    {"id":"q-sound-vibration-0","question":{"zh":"声音到底是什么？","en":"What exactly is sound?"},"chain":["sound-vibration","oscillation"],"target":{"node":"sound-vibration","href":"../sound-vibration/#step2"},"prompts":[{"node":"sound-vibration","ask":{"zh":"敲鼓时鼓面在动，放在鼓面上的米粒为什么会跳起来？","en":"When you beat a drum, why do rice grains sitting on the drumhead jump?"}},{"node":"oscillation","ask":{"zh":"鼓面振动得越快、幅度越大，听到的声音在音高和响度上各有什么变化？","en":"If the drumhead vibrates faster and with a bigger swing, what changes in pitch and in loudness?"}}],"reveal":{"zh":"声音就是物体的振动传到耳朵：振动越快音越高，幅度越大声越响，没有介质传不过去。","en":"Sound is an object's vibration reaching your ears: faster vibration means higher pitch, bigger swing means louder sound, and with no medium it cannot travel at all."},"source":"../sound-vibration/#step2","lesson":"sound-vibration","stage":"primary","group":"waves"},
    {"id":"q-water-cycle-0","question":{"zh":"水循环里的水为什么不会越来越多或越来越少？","en":"Why does the water in the cycle neither pile up nor run out?"},"chain":["water-cycle","feedback"],"target":{"node":"water-cycle","href":"../water-cycle/#step4"},"prompts":[{"node":"water-cycle","ask":{"zh":"海洋、空气、陆地三个水库之间，水通过蒸发、降水、径流流动，总量变了吗？","en":"Water flows between ocean, air and land through evaporation, rain and runoff — does the total amount change?"}},{"node":"feedback","ask":{"zh":"如果某处水变多了，流出会变快还是变慢？这种“多了就流走得更快”会让水量稳定下来吗？","en":"If one store holds more water, does its outflow speed up or slow down? Does \"more water flows out faster\" settle the amount at a steady value?"}}],"reveal":{"zh":"水只是在三个水库之间搬家，总量守恒；某处水多则流出加快、水少则流出减慢，于是各处水量收敛到稳定值。","en":"Water only moves between the three stores, so the total is conserved; a fuller store drains faster and an emptier one drains slower, so each store settles at a steady value."},"source":"../water-cycle/#step4","lesson":"water-cycle","stage":"primary","group":"systems"},
    {"id":"q-blood-circulation-0","question":{"zh":"为什么毛细血管里血流最慢？","en":"Why is blood slowest in the capillaries?"},"chain":["blood-circulation"],"target":{"node":"blood-circulation","href":"../blood-circulation/#step3"},"prompts":[{"node":"blood-circulation","ask":{"zh":"心脏的瓣膜和四个腔保证血液单向流动——如果瓣膜关不严，血液会怎样流？","en":"The heart's valves and four chambers keep blood flowing one way — if a valve could not close properly, what would the blood do?"}}],"reveal":{"zh":"同一流量下总横截面积越大流速越小，毛细血管总面积最大，所以血流最慢，正好让物质有时间交换。","en":"At the same flow, the wider the total cross-section the slower the flow; capillaries have the largest total area, so blood moves slowest there — exactly what lets substances exchange in time."},"source":"../blood-circulation/#step3","lesson":"blood-circulation","stage":"junior","group":"life"},
    {"id":"q-buoyancy-archimedes-0","question":{"zh":"钢这么重，船为什么还能浮？","en":"Steel is heavy, so why does a ship float?"},"chain":["buoyancy-archimedes","net-force"],"target":{"node":"buoyancy-archimedes","href":"../buoyancy-archimedes/#step1"},"prompts":[{"node":"buoyancy-archimedes","ask":{"zh":"钢的密度比水大得多，空心船排开的水和实心钢块排开的水，哪个更重？","en":"Steel is far denser than water — which displaces heavier water, a hollow ship or a solid steel block?"}},{"node":"net-force","ask":{"zh":"船浮着不动时，浮力和重力什么关系？浮力 F = ρ液·g·V排 里，哪个量是船的设计能改变的？","en":"While the ship floats still, how do buoyant force and gravity compare? In F = ρ·g·V, which quantity can the ship's design change?"}}],"reveal":{"zh":"船是空心的，排开的水很重，浮力等于排开水的重量，大到足以托住钢船；浮着时浮力与重力相等。","en":"A ship is hollow, so it displaces very heavy water; buoyant force equals the weight of that water, enough to hold up the steel, and while floating it equals gravity."},"source":"../buoyancy-archimedes/#step1","lesson":"buoyancy-archimedes","stage":"junior","group":"waves"},
    {"id":"q-combustion-triangle-0","question":{"zh":"为什么这样灭火有效？","en":"Why does that way of putting out a fire work?"},"chain":["combustion-triangle"],"target":{"node":"combustion-triangle","href":"../combustion-triangle/#step3"},"prompts":[{"node":"combustion-triangle","ask":{"zh":"燃烧要可燃物、氧气、着火温度三者同时具备——盖上锅盖灭火，是抽掉了哪一条？","en":"Burning needs fuel, oxygen and ignition temperature all at once — when you smother a pan fire with a lid, which leg are you removing?"}}],"reveal":{"zh":"盖锅盖隔绝了氧气，三条腿缺了一条，火就灭了；灭火的办法都是抽掉三者之一。","en":"The lid cuts off the oxygen, so one leg of the triangle is gone and the fire dies; every way of putting out a fire removes one of the three."},"source":"../combustion-triangle/#step3","lesson":"combustion-triangle","stage":"junior","group":"matter"},
    {"id":"q-contour-lines-0","question":{"zh":"怎么从地图上看出哪里陡？","en":"How can you tell from a map where it is steep?"},"chain":["contour-lines","derivative"],"target":{"node":"contour-lines","href":"../contour-lines/#step1"},"prompts":[{"node":"contour-lines","ask":{"zh":"等高线越密，坡越陡还是越缓？相邻两条线之间，海拔差多少？","en":"Where contour lines crowd together, is the slope steeper or gentler? How much altitude changes between neighbouring lines?"}},{"node":"derivative","ask":{"zh":"水沿垂直于等高线的最陡方向往低处流——这个“最陡方向”和变化率有什么关系？","en":"Water runs downhill perpendicular to the contour lines, along the steepest direction — what does that steepest direction have to do with a rate of change?"}}],"reveal":{"zh":"等高线越密坡越陡，相邻线差一个等高距；水往最陡方向流，也就是高度变化最快的方向。","en":"Closer lines mean a steeper slope, with one contour interval between neighbours; water flows along the steepest descent, the direction where height changes fastest."},"source":"../contour-lines/#step1","lesson":"contour-lines","stage":"junior","group":"earth"},
    {"id":"q-density-0","question":{"zh":"为什么有的东西浮、有的东西沉？","en":"Why do some things float and others sink?"},"chain":["density","slope"],"target":{"node":"density","href":"../density/#step2"},"prompts":[{"node":"density","ask":{"zh":"同种均匀材料，质量和体积成正比——画成质量-体积图，是一条直线吗？斜率是什么？","en":"For one uniform material, mass is proportional to volume — plotted as mass against volume, is it a straight line, and what is its slope?"}},{"node":"slope","ask":{"zh":"两块材料，图上斜率大的密度大还是小？密度大的放进水里会怎样？","en":"Of two materials, does the steeper line mean higher or lower density? What happens in water to the denser one?"}}],"reveal":{"zh":"质量÷体积 = 密度，图上斜率就是密度；密度比水大的下沉，比水小的上浮。","en":"Mass ÷ volume is density, which is exactly the slope of that line; denser than water sinks, less dense floats."},"source":"../density/#step2","lesson":"density","stage":"junior","group":"measurement"},
    {"id":"q-dissolution-saturation-0","question":{"zh":"饱和是不是意味着溶解停止了？","en":"Does saturation mean dissolving has stopped?"},"chain":["dissolution-saturation"],"target":{"node":"dissolution-saturation","href":"../dissolution-saturation/#step2"},"prompts":[{"node":"dissolution-saturation","ask":{"zh":"饱和时溶解和结晶的速率相等——速率相等，意味着水里的溶质不再增加了吗？还是溶解仍在进行？","en":"At saturation, dissolving and crystallising run at equal rates — does that mean the dissolved amount stops changing, or is dissolving still going on?"}}],"reveal":{"zh":"饱和不是停止，而是动态平衡：溶解和结晶同时进行、速率相等，所以总量看起来不变；降温或蒸发会打破平衡，让多余溶质结晶出来。","en":"Saturation is not a stop but a dynamic balance: dissolving and crystallising continue at equal rates, so the total looks unchanged; cooling or evaporation breaks the balance and extra solute crystallises out."},"source":"../dissolution-saturation/#step2","lesson":"dissolution-saturation","stage":"junior","group":"matter"},
    {"id":"q-energy-pyramid-0","question":{"zh":"为什么顶级捕食者那么少？","en":"Why are top predators so rare?"},"chain":["work-energy","energy-pyramid","feedback"],"target":{"node":"energy-pyramid","href":"../energy-pyramid/#step1"},"prompts":[{"node":"work-energy","ask":{"zh":"阳光固定的能量逐级传递时，每一级大约剩下多少？剩下的能量去哪了？","en":"As the Sun's fixed energy passes up the levels, roughly how much survives each step, and where does the rest go?"}},{"node":"energy-pyramid","ask":{"zh":"顶级捕食者处在第几级？按每级约剩一成算，它能分到的能量是生产者的几分之几？","en":"Which level do top predators sit at? At roughly a tenth surviving each step, what fraction of the producers' energy reaches them?"}},{"node":"feedback","ask":{"zh":"如果顶级捕食者变多了，对下级会产生什么连锁影响？这种反馈会让数量稳定还是失控？","en":"If top predators grew more numerous, what knock-on effect would that have down the levels? Would that feedback steady the numbers or run away?"}}],"reveal":{"zh":"每级约剩一成，顶级捕食者分到的能量只有生产者的千分之一左右，所以养得起的数量很少；数量变化会沿网传开又反推回来。","en":"About a tenth survives each level, so top predators get only around a thousandth of the producers' energy — very few can be supported, and changes ripple through the web and push back."},"source":"../energy-pyramid/#step1","lesson":"energy-pyramid","stage":"junior","group":"systems"},
    {"id":"q-equation-balancing-0","question":{"zh":"怎样把一个化学方程式配平？","en":"How do I balance a chemical equation?"},"chain":["equation-balancing"],"target":{"node":"equation-balancing","href":"../equation-balancing/#step0"},"prompts":[{"node":"equation-balancing","ask":{"zh":"配平要让每种原子两边个数相等——为什么只能调系数，不能改化学式里的下标？","en":"Balancing must equalise every element's count on both sides — why may you only change coefficients, never the subscripts in a formula?"}}],"reveal":{"zh":"下标是物质本身的组成，改了就变成另一种物质；系数只改分子个数，不改物质种类，依据是反应中原子种类与总数不变。","en":"Subscripts are part of a substance's identity — changing them makes a different substance; coefficients only change how many molecules react, which keeps every atom's kind and total unchanged."},"source":"../equation-balancing/#step0","lesson":"equation-balancing","stage":"junior","group":"matter"},
    {"id":"q-eye-vision-0","question":{"zh":"为什么近视要戴凹透镜？","en":"Why does short-sightedness need a concave lens?"},"chain":["eye-vision","snell"],"target":{"node":"eye-vision","href":"../eye-vision/#step2"},"prompts":[{"node":"eye-vision","ask":{"zh":"近视是眼轴偏长，焦点落在视网膜前还是后？要把焦点往后推，该用会聚光的透镜还是发散光的透镜？","en":"In short-sightedness the eyeball is too long, so does the focus fall in front of or behind the retina? To push it back, do you need a converging or a diverging lens?"}},{"node":"snell","ask":{"zh":"光从空气进入透镜会折射——凹透镜让光发散还是会聚？发散之后焦点往哪个方向移？","en":"Light refracts entering a lens — does a concave lens spread light out or bring it together? And which way does spreading move the focus?"}}],"reveal":{"zh":"近视焦点在视网膜前，凹透镜把光发散开，焦点后移到视网膜上；远视正好相反。","en":"In short-sightedness the focus lands in front of the retina; a concave lens spreads the light so the focus shifts back onto the retina. Long-sightedness is the reverse."},"source":"../eye-vision/#step2","lesson":"eye-vision","stage":"junior","group":"waves"},
    {"id":"q-food-web-0","question":{"zh":"为什么顶级捕食者总是很少？","en":"Why are top predators always few?"},"chain":["food-web"],"target":{"node":"food-web","href":"../food-web/#step1"},"prompts":[{"node":"food-web","ask":{"zh":"食物网里能量每级约剩十分之一——顶级捕食者要养活自己，需要下级提供多少能量？","en":"In a food web about a tenth of the energy survives each step — how much energy must the lower levels supply to support one top predator?"}}],"reveal":{"zh":"能量逐级只剩一成，顶级捕食者站在最高处，分到的能量最少，所以数量总是最少；食物来源越多，网越稳。","en":"With only about a tenth surviving each step, top predators at the highest level get the least energy, so they are always fewest; more food sources make the web steadier."},"source":"../food-web/#step1","lesson":"food-web","stage":"junior","group":"life"},
    {"id":"q-inequalities-0","question":{"zh":"解不等式为什么乘负数要变号？","en":"Why does multiplying by a negative flip the inequality?"},"chain":["inequalities","slope"],"target":{"node":"inequalities","href":"../inequalities/#step3"},"prompts":[{"node":"inequalities","ask":{"zh":"不等式两边同时加一个数，不等号方向变吗？同时乘一个正数呢？","en":"Add the same number to both sides of an inequality — does the sign change? What about multiplying both sides by a positive number?"}},{"node":"slope","ask":{"zh":"把不等式想成一条直线：乘负数相当于把直线怎样翻转？翻转后，原来大的那边跑到哪边去了？","en":"Think of the inequality as a line — what does multiplying by a negative do to that line? After the flip, where does the side that was bigger end up?"}}],"reveal":{"zh":"加减和乘正数都不改变大小关系；乘负数相当于把数轴翻转，原来大的一边翻到了小的一边，所以不等号必须变向。","en":"Adding, subtracting and multiplying by a positive keep the order; multiplying by a negative flips the number line, so the side that was bigger lands on the smaller side — the sign must flip."},"source":"../inequalities/#step3","lesson":"inequalities","stage":"junior","group":"math"},
    {"id":"q-inverse-proportion-0","question":{"zh":"怎样判断是正比例还是反比例？","en":"How do you tell direct from inverse proportion?"},"chain":["inverse-proportion","slope"],"target":{"node":"inverse-proportion","href":"../inverse-proportion/#step2"},"prompts":[{"node":"inverse-proportion","ask":{"zh":"x·y = k 不变时，x 变大，y 怎样变？画出来是直线还是曲线？","en":"With x·y = k fixed, when x grows, what happens to y? Does the graph come out straight or curved?"}},{"node":"slope","ask":{"zh":"正比例的图是一条过原点的直线，斜率是比值——反比例的“斜率”为什么不能这样看？","en":"Direct proportion graphs as a straight line through the origin whose slope is the ratio — why can't you read inverse proportion the same way?"}}],"reveal":{"zh":"乘积不变，一个变大另一个按比例变小，图像是双曲线；看 x·y 是否恒定就能区分正比例和反比例。","en":"With the product fixed, one growing means the other shrinks in proportion, and the graph is a hyperbola; checking whether x·y stays constant tells direct from inverse proportion."},"source":"../inverse-proportion/#step2","lesson":"inverse-proportion","stage":"junior","group":"math"},
    {"id":"q-latitude-longitude-0","question":{"zh":"为什么世界地图上高纬度的地方显得特别大？","en":"Why do high-latitude regions look so big on a world map?"},"chain":["latitude-longitude","unit-circle"],"target":{"node":"latitude-longitude","href":"../latitude-longitude/#step1"},"prompts":[{"node":"latitude-longitude","ask":{"zh":"纬线周长随 cos 纬度缩小——赤道和北纬 60° 的纬线圈，哪个长？长几倍？","en":"A parallel's length shrinks with cos(latitude) — which is longer, the equator or the 60° N parallel, and by what factor?"}},{"node":"unit-circle","ask":{"zh":"把地球想成单位圆上的角度：经度差 15° 对应几小时？为什么球面摊成平面必然变形？","en":"Think of the Earth in terms of angles on a circle — how many hours does 15° of longitude correspond to? And why must flattening a sphere distort it?"}}],"reveal":{"zh":"高纬纬线圈短得多，但地图常把它们拉长，所以显得特别大；15° 经度对应 1 小时，球面无法不经变形摊平。","en":"High-latitude parallels are much shorter, but maps stretch them, so they look huge; 15° of longitude is 1 hour, and a sphere cannot be flattened without distortion."},"source":"../latitude-longitude/#step1","lesson":"latitude-longitude","stage":"junior","group":"earth"},
    {"id":"q-mean-median-mode-0","question":{"zh":"为什么工资用中位数而不是平均数？","en":"Why are salaries reported as a median, not a mean?"},"chain":["mean-median-mode","variance"],"target":{"node":"mean-median-mode","href":"../mean-median-mode/#step1"},"prompts":[{"node":"mean-median-mode","ask":{"zh":"一个极端大的工资加入后，平均数、中位数、众数哪个动得最多？","en":"Add one extremely large salary — which moves most: the mean, the median, or the mode?"}},{"node":"variance","ask":{"zh":"中位数不怕极端值，但它丢失了什么信息？为什么工资报道常用中位数？","en":"The median resists extreme values, but what information does it throw away? Why do salary reports prefer it?"}}],"reveal":{"zh":"极端值会拉动平均数，却几乎不动中位数和众数；工资分布右偏严重时，中位数更能代表典型水平。","en":"An extreme value drags the mean but barely moves the median or mode; with salaries skewed high, the median better represents the typical level."},"source":"../mean-median-mode/#step1","lesson":"mean-median-mode","stage":"junior","group":"measurement"},
    {"id":"q-mechanical-energy-0","question":{"zh":"过山车为什么翻得过圆环？","en":"Why does a roller coaster get round the loop?"},"chain":["mechanical-energy","work-energy","net-force"],"target":{"node":"mechanical-energy","href":"../mechanical-energy/#step1"},"prompts":[{"node":"mechanical-energy","ask":{"zh":"无摩擦时动能加势能守恒——过山车从高处冲下来，高度换成了什么？","en":"Without friction, kinetic plus potential energy is conserved — as the coaster dives from a height, what does the height turn into?"}},{"node":"work-energy","ask":{"zh":"冲上圆环顶端时，速度由高度差决定——为什么圆环的最低高度是 2.5R？","en":"Speed at the loop's top is set by the height difference — why must the start be at least 2.5R high?"}},{"node":"net-force","ask":{"zh":"在圆环顶端，重力和支持力的合力提供向心力——如果速度太小，合力不够会怎样？","en":"At the loop's top, gravity plus the track's push supply the centripetal force — if the speed is too small and the net force falls short, what happens?"}}],"reveal":{"zh":"高度换成速度，冲上圆环需要足够的动能；2.5R 保证顶端仍有速度、合力仍能提供向心力，车才不会掉下来。","en":"Height turns into speed, and climbing the loop needs enough kinetic energy; 2.5R guarantees speed remains at the top so the net force can still supply the centripetal force and the car stays on the track."},"source":"../mechanical-energy/#step1","lesson":"mechanical-energy","stage":"junior","group":"systems"},
    {"id":"q-molecules-atoms-0","question":{"zh":"水烧开和水通电有什么本质区别？","en":"What is the real difference between boiling water and electrolysing it?"},"chain":["molecules-atoms"],"target":{"node":"molecules-atoms","href":"../molecules-atoms/#step2"},"prompts":[{"node":"molecules-atoms","ask":{"zh":"水烧开时，水分子本身变了吗？变的只是分子的位置和间距吗？","en":"When water boils, do the water molecules themselves change? Or only their positions and spacing?"}}],"reveal":{"zh":"烧开是物理变化，只改变分子的位置与间距；通电是化学变化，拆开水分子、让原子重组成氢气和氧气，原子种类和总数不变。","en":"Boiling is a physical change — only positions and spacing change; electrolysis is a chemical change that tears water molecules apart and rebuilds the atoms into hydrogen and oxygen, with atom kinds and totals unchanged."},"source":"../molecules-atoms/#step2","lesson":"molecules-atoms","stage":"junior","group":"matter"},
    {"id":"q-ohms-law-0","question":{"zh":"为什么灯泡的电流不跟电压成正比？","en":"Why isn’t a bulb’s current proportional to voltage?"},"chain":["simple-circuits","ohms-law"],"target":{"node":"ohms-law","href":"../ohms-law/#step0"},"prompts":[{"node":"simple-circuits","ask":{"zh":"完整闭合的回路里电流处处相同——调高电压，电流怎样变？调大电阻呢？","en":"In a complete closed loop the current is the same everywhere — raise the voltage, what happens to the current? Raise the resistance?"}},{"node":"ohms-law","ask":{"zh":"灯丝的电流-电压曲线是弯的，不是直线——这说明灯丝的电阻是恒定的吗？温度起了什么作用？","en":"A filament's current-voltage curve bends instead of staying straight — does that mean its resistance is constant? What role does temperature play?"}}],"reveal":{"zh":"对定值电阻电流与电压成正比；灯丝发热后电阻变大，曲线变弯，所以电流不再跟电压成正比。","en":"For a fixed resistor current is proportional to voltage; a filament's resistance grows as it heats, bending the curve, so its current no longer tracks voltage proportionally."},"source":"../ohms-law/#step0","lesson":"ohms-law","stage":"junior","group":"circuits"},
    {"id":"q-ph-scale-0","question":{"zh":"pH 差 3 到底差多少倍？","en":"How many times stronger is an acid 3 pH units lower?"},"chain":["ph-scale"],"target":{"node":"ph-scale","href":"../ph-scale/#step1"},"prompts":[{"node":"ph-scale","ask":{"zh":"pH 每差 1，[H⁺] 差几倍？pH 差 3 呢？","en":"Each pH unit apart means how many times more [H⁺]? And 3 units apart?"}}],"reveal":{"zh":"pH 是对数刻度，每差 1 个单位 [H⁺] 相差 10 倍，差 3 就是 10³ = 1000 倍；酸再稀释也只趋近 7，不会变碱。","en":"pH is logarithmic: one unit is a factor of 10 in [H⁺], so 3 units is 10³ = 1000 times; diluting an acid only approaches 7, never turns alkaline."},"source":"../ph-scale/#step1","lesson":"ph-scale","stage":"junior","group":"matter"},
    {"id":"q-polygon-angles-0","question":{"zh":"为什么多边形内角和是 (n−2)×180°？","en":"Why is a polygon's angle sum (n − 2) × 180°?"},"chain":["polygon-angles","unit-circle"],"target":{"node":"polygon-angles","href":"../polygon-angles/#step2"},"prompts":[{"node":"polygon-angles","ask":{"zh":"n 边形能分成几个三角形？每个三角形内角和是多少？","en":"Into how many triangles can an n-gon be split? What is each triangle's angle sum?"}},{"node":"unit-circle","ask":{"zh":"内角和是 (n−2)×180°，外角和是 360°——绕一圈转过的角度，为什么和边数无关？","en":"Interior sums to (n − 2) × 180° and exterior to 360° — why does the total turning around a full loop not depend on the number of sides?"}}],"reveal":{"zh":"从一个顶点连对角线，分成 n−2 个三角形，内角和就是 (n−2)×180°；外角是每步转过的角度，绕一圈总共转 360°，与边数无关。","en":"Diagonals from one vertex split it into n − 2 triangles, giving (n − 2) × 180°; each exterior angle is the turn at one step, and a full loop always turns 360°, whatever the number of sides."},"source":"../polygon-angles/#step2","lesson":"polygon-angles","stage":"junior","group":"math"},
    {"id":"q-pressure-0","question":{"zh":"为什么小力能顶起大重物？","en":"Why can a small force lift a big weight?"},"chain":["pressure","work-energy"],"target":{"node":"pressure","href":"../pressure/#step0"},"prompts":[{"node":"pressure","ask":{"zh":"同样的力，接触面积越小压强越大——针尖和手指按同一个图钉，哪个压强大？","en":"The same force on a smaller area means higher pressure — pressing one drawing pin, is the pressure bigger at the point or at the flat end?"}},{"node":"work-energy","ask":{"zh":"密闭液体中压强处处相等——小活塞上加小力，大活塞为什么能顶起大重物？能量从哪里来？","en":"Pressure is equal everywhere in a sealed liquid — why can a small force on a small piston lift a big weight on a big piston? Where does the energy come from?"}}],"reveal":{"zh":"p = F/S，小面积上小力产生大压强，传到大面积上就是大力；小活塞移动距离长、大活塞移动距离短，能量仍守恒。","en":"p = F/S: a small force on a small area makes a large pressure, which on a large area becomes a large force; the small piston travels far and the big one travels little, so energy is still conserved."},"source":"../pressure/#step0","lesson":"pressure","stage":"junior","group":"waves"},
    {"id":"q-real-number-line-0","question":{"zh":"√2 到底在数轴的哪里？","en":"Where exactly is √2 on the number line?"},"chain":["real-number-line","unit-circle"],"target":{"node":"real-number-line","href":"../real-number-line/#step2"},"prompts":[{"node":"real-number-line","ask":{"zh":"单位正方形的对角线有多长？这条线段能放到数轴上吗？","en":"How long is a unit square's diagonal? Can that length be placed on the number line?"}},{"node":"unit-circle","ask":{"zh":"√2 不能写成分数，小数不结束不循环——二分逼近是怎样一点点夹住它的？","en":"√2 is not a fraction and its decimals neither stop nor repeat — how does bisection close in on it step by step?"}}],"reveal":{"zh":"对角线长 √2，它在数轴上有确定的位置；不能写成分数，但可用二分法无限逼近，夹在两个越来越近的有理数之间。","en":"The diagonal is √2 long and has an exact place on the number line; it is no fraction, but bisection traps it between rational numbers that draw ever closer."},"source":"../real-number-line/#step2","lesson":"real-number-line","stage":"junior","group":"math"},
    {"id":"q-seasons-orbit-0","question":{"zh":"为什么会有四季？","en":"Why are there seasons?"},"chain":["seasons-orbit","sine"],"target":{"node":"seasons-orbit","href":"../seasons-orbit/#step2"},"prompts":[{"node":"seasons-orbit","ask":{"zh":"地轴倾斜约 23.4° 且方向不变——一年里太阳直射点在南北回归线之间怎样移动？","en":"Earth's axis tilts about 23.4° in a fixed direction — how does the overhead point of the Sun move between the tropics over a year?"}},{"node":"sine","ask":{"zh":"直射点移动时，正午太阳高度和昼长怎样跟着变？这种变化像不像正弦波？","en":"As the overhead point moves, how do noon Sun height and day length change? Does that variation look like a sine wave?"}}],"reveal":{"zh":"直射点一年往返一次，正午高度和昼长随之周期变化，就是四季；日地距离只变约 3%，不是原因。","en":"The overhead point swings back and forth once a year, and noon height and day length vary with it — that is the seasons; the Earth-Sun distance varies only about 3% and is not the cause."},"source":"../seasons-orbit/#step2","lesson":"seasons-orbit","stage":"junior","group":"earth"},
    {"id":"q-series-parallel-0","question":{"zh":"为什么家里的灯一个坏了其他还亮？","en":"Why do the other lights stay on when one bulb fails?"},"chain":["simple-circuits","series-parallel"],"target":{"node":"series-parallel","href":"../series-parallel/#step2"},"prompts":[{"node":"simple-circuits","ask":{"zh":"串联时电流处处相同——拧下一个灯泡，整个回路的电流会怎样？","en":"In series the current is the same everywhere — unscrew one bulb, what happens to the current in the whole loop?"}},{"node":"series-parallel","ask":{"zh":"并联时电压相同、电流按电阻反比分——家里一个灯坏了，其他灯的电压变了吗？为什么还亮？","en":"In parallel the voltage is the same and current divides inversely with resistance — when one home bulb fails, does the voltage on the others change? Why do they stay lit?"}}],"reveal":{"zh":"串联是一条路，断了全灭；并联是各走各的路，电压不变、各支路独立，所以一个坏了其他还亮——这就是家庭电器并联的原因。","en":"Series is a single path — break it and all go dark; parallel gives each bulb its own path at the same voltage, independently, so one failing leaves the rest lit — which is why home appliances are wired in parallel."},"source":"../series-parallel/#step2","lesson":"series-parallel","stage":"junior","group":"circuits"},
    {"id":"q-similarity-scaling-0","question":{"zh":"为什么放大一倍，面积和体积不止一倍？","en":"Why do area and volume grow by more than the scale factor?"},"chain":["similarity-scaling","pinhole-ratio"],"target":{"node":"similarity-scaling","href":"../similarity-scaling/#step2"},"prompts":[{"node":"similarity-scaling","ask":{"zh":"放大 k 倍，长度、面积、体积各乘几？为什么面积和体积的倍数不一样？","en":"Enlarge by k — lengths, areas and volumes multiply by what? Why are the area and volume factors different?"}},{"node":"pinhole-ratio","ask":{"zh":"照相小孔成像里，物距和像距的比决定放大倍数——放大倍数变了，面积的倍数怎样跟着变？","en":"In pinhole imaging the ratio of object to image distance sets the scale — when the scale changes, how does the area factor follow?"}}],"reveal":{"zh":"长度×k、面积×k²、体积×k³，因为面积是两条边的乘积、体积是三条边的乘积；放大一倍，面积变 4 倍、体积变 8 倍。","en":"Lengths ×k, areas ×k², volumes ×k³, because area multiplies two sides and volume three; doubling the size quadruples area and multiplies volume by eight."},"source":"../similarity-scaling/#step2","lesson":"similarity-scaling","stage":"junior","group":"math"},
    {"id":"q-simultaneous-equations-0","question":{"zh":"两个方程什么时候有唯一解？","en":"When do two equations have exactly one solution?"},"chain":["simultaneous-equations","slope"],"target":{"node":"simultaneous-equations","href":"../simultaneous-equations/#step4"},"prompts":[{"node":"simultaneous-equations","ask":{"zh":"两个一次方程的公共解是两条直线的交点——两条直线相交、平行、重合时，各有几个公共解？","en":"The common solution of two linear equations is where two lines cross — for crossing, parallel and coincident lines, how many common solutions are there?"}},{"node":"slope","ask":{"zh":"直线的斜率不同，相交情况怎样？斜率相同但截距不同呢？","en":"What happens when the lines have different slopes? Same slope but different intercepts?"}}],"reveal":{"zh":"斜率不同必相交于唯一解；斜率相同、截距不同则平行无解；斜率截距都相同则重合，有无穷多解。","en":"Different slopes always cross at exactly one solution; same slope with different intercepts means parallel lines and no solution; same slope and intercept means coincident lines and infinitely many solutions."},"source":"../simultaneous-equations/#step4","lesson":"simultaneous-equations","stage":"junior","group":"math"},
    {"id":"q-solid-geometry-0","question":{"zh":"立方体能被切出几种形状？","en":"What shapes can a cube be cut into?"},"chain":["solid-geometry","integral"],"target":{"node":"solid-geometry","href":"../solid-geometry/#step2"},"prompts":[{"node":"solid-geometry","ask":{"zh":"平面截立方体，能切出几边形？最多几边？为什么不能切出七边形？","en":"Slicing a cube with a plane, how many sides can the cut have? What is the most, and why not seven?"}},{"node":"integral","ask":{"zh":"切片累加能得到金字塔体积 1/3——把立体切成薄片再加起来，和积分有什么关系？","en":"Stacking slices gives a pyramid's volume as 1/3 — what does adding up thin slices have to do with integration?"}}],"reveal":{"zh":"平面截立方体可得 3、4、5、6 边形，立方体只有 6 个面所以最多 6 边；薄片累加就是积分的思想，金字塔体积是同底同高柱体的 1/3。","en":"A plane cut gives 3, 4, 5 or 6 sides — six faces means six at most; adding thin slices is exactly the idea of integration, and a pyramid's volume is 1/3 of the prism on the same base and height."},"source":"../solid-geometry/#step2","lesson":"solid-geometry","stage":"junior","group":"math"},
    {"id":"q-sound-waves-0","question":{"zh":"同一个音，为什么钢琴和小提琴听起来不同？","en":"Why does the same note sound different on a piano and a violin?"},"chain":["superposition","sound-waves","fourier"],"target":{"node":"sound-waves","href":"../sound-waves/#step1"},"prompts":[{"node":"superposition","ask":{"zh":"两个相近频率的声音叠加会产生拍——拍的快慢由什么决定？","en":"Two close frequencies played together produce beats — what sets how fast the beats come?"}},{"node":"sound-waves","ask":{"zh":"同一个音，钢琴和小提琴的波形有什么不同？谐波的强弱决定什么？","en":"For the same note, how do a piano's and a violin's waveforms differ? What do the strengths of the harmonics decide?"}},{"node":"fourier","ask":{"zh":"傅里叶分析能把复杂波形拆成什么？拆开后怎样解释音色不同？","en":"What does Fourier analysis break a complex waveform into? How does that explain different timbres?"}}],"reveal":{"zh":"拍来自相近频率的叠加；音色由谐波的组成与强弱决定，傅里叶分析把波形拆成不同频率的正弦波，组成不同听起来就不同。","en":"Beats come from superposing close frequencies; timbre is set by which harmonics are present and how strong they are — Fourier analysis splits a waveform into sine waves of different frequencies, and different mixtures sound different."},"source":"../sound-waves/#step1","lesson":"sound-waves","stage":"junior","group":"waves"},
    {"id":"q-three-views-0","question":{"zh":"为什么两个视图不够，要三个？","en":"Why are two views not enough, and why do we need three?"},"chain":["three-views","vectors"],"target":{"node":"three-views","href":"../three-views/#step3"},"prompts":[{"node":"three-views","ask":{"zh":"只看主视图，能确定每格堆了几块吗？","en":"From the front view alone, can you tell how many blocks are stacked in each square?"}},{"node":"vectors","ask":{"zh":"只有两个视图时为什么可能有多种堆法？第三个视图补上了什么信息？","en":"Why can two views leave several possible stackings? What information does the third view add?"}}],"reveal":{"zh":"两个视图只能确定两个方向的位置，高度方向的信息不全；三个视图从三个方向对齐，才能唯一还原立体。","en":"Two views fix positions in only two directions and leave heights underdetermined; three aligned views from three directions pin down the stack uniquely."},"source":"../three-views/#step3","lesson":"three-views","stage":"junior","group":"math"},
    {"id":"q-activation-energy-0","question":{"zh":"为什么升温能让反应快这么多？","en":"Why does warming speed a reaction up so much?"},"chain":["probability","activation-energy","montecarlo"],"target":{"node":"activation-energy","href":"../activation-energy/#step2"},"prompts":[{"node":"probability","ask":{"zh":"只有能量超过能量山的分子才能反应——升温时，超过山顶的分子比例变大还是变小？","en":"Only molecules with energy above the hill can react — when temperature rises, does the share above the top grow or shrink?"}},{"node":"activation-energy","ask":{"zh":"k = A·e^(−Eₐ/RT) 里，T 变大时指数部分怎样变？为什么反应速率对温度这么敏感？","en":"In k = A·e^(−Eₐ/RT), what happens to the exponent as T grows? Why is the rate so sensitive to temperature?"}},{"node":"montecarlo","ask":{"zh":"如果用随机抽样模拟一群分子的能量，升温后能量分布的形状怎样变？","en":"If you simulate a crowd of molecules' energies by random sampling, how does the energy distribution's shape change on warming?"}}],"reveal":{"zh":"升温让超过活化能的分子比例指数式增加，所以速率随温度急剧上升；催化剂则是降低能量山本身。","en":"Warming raises the share of molecules above the activation energy exponentially, so the rate climbs steeply with temperature; a catalyst instead lowers the hill itself."},"source":"../activation-energy/#step2","lesson":"activation-energy","stage":"senior","group":"systems"},
    {"id":"q-atmospheric-circulation-0","question":{"zh":"为什么赤道多雨、副热带多沙漠？","en":"Why is the equator rainy and the subtropics desert-prone?"},"chain":["atmospheric-circulation","seasons-orbit"],"target":{"node":"atmospheric-circulation","href":"../atmospheric-circulation/#step2"},"prompts":[{"node":"atmospheric-circulation","ask":{"zh":"赤道受热多，空气上升还是下沉？上升的空气冷却后，水汽会怎样？","en":"The equator is heated most — does air there rise or sink? What happens to its water vapour as it cools on rising?"}},{"node":"seasons-orbit","ask":{"zh":"空气在副热带下沉时，是变干还是变湿？下沉区对应多雨还是多沙漠？","en":"As air sinks in the subtropics, does it dry out or moisten? Does a sinking region mean rain or desert?"}}],"reveal":{"zh":"赤道空气上升冷却，水汽凝结成雨；空气流到副热带下沉增温，抑制成云，所以副热带多沙漠。","en":"Equatorial air rises and cools, condensing its vapour into rain; by the subtropics the air sinks and warms, suppressing clouds — hence deserts."},"source":"../atmospheric-circulation/#step2","lesson":"atmospheric-circulation","stage":"senior","group":"earth"},
    {"id":"q-auctions-0","question":{"zh":"怎样的拍卖规则能让人说真话？","en":"Which auction rule makes people bid truthfully?"},"chain":["auctions","game-theory"],"target":{"node":"auctions","href":"../auctions/#step2"},"prompts":[{"node":"auctions","ask":{"zh":"第一价格拍卖里，为什么中标者总想压一点价？第二价格里，说出真实估值会亏吗？","en":"In a first-price auction, why does the winner always want to shade the bid a little? In a second-price auction, can telling your true value lose you money?"}},{"node":"game-theory","ask":{"zh":"“占优策略”是什么意思？为什么第二价格里的真话策略不用猜对手出什么？","en":"What does a “dominant strategy” mean? Why does truth-telling in second-price need no guess about rivals?"}}],"reveal":{"zh":"第二价格拍卖里，说真话是占优策略：出价只决定你是否中标，不决定你付多少钱，付的是第二高价；第一价格里中标即按自己出价付款，所以人人压价。英式等价于第二价格、荷式等价于第一价格，平均收益相等；真值不确定时还要小心赢家的诅咒。","en":"In a second-price auction truth-telling is dominant: your bid only decides whether you win, not what you pay — you pay the second-highest bid. In a first-price auction you pay your own bid when you win, so everyone shades; English matches second-price and Dutch matches first-price with equal average revenue, and with uncertain true values, beware the winner's curse."},"source":"../auctions/#step2","lesson":"auctions","stage":"senior","group":"society"},
    {"id":"q-binomial-normal-0","question":{"zh":"为什么扔很多次硬币，正面数像一口钟？","en":"Why does the head count of many coin flips look like a bell?"},"chain":["binomial-normal","gaussian","probability"],"target":{"node":"binomial-normal","href":"../binomial-normal/#step3"},"prompts":[{"node":"binomial-normal","ask":{"zh":"n 次独立试验恰好 k 次成功的概率怎么算？均值和方差是多少？","en":"How do you compute the chance of exactly k successes in n independent trials? What are its mean and variance?"}},{"node":"gaussian","ask":{"zh":"n 增大时，二项柱状图贴近什么样的曲线？“同均值同标准差”是什么意思？","en":"As n grows, what curve do the binomial bars hug? What does “same mean and same spread” mean?"}},{"node":"probability","ask":{"zh":"钟形曲线的高度代表什么？曲线下的面积为什么等于概率？","en":"What does the height of the bell curve stand for? Why does area under the curve equal probability?"}}],"reveal":{"zh":"由杨辉三角数路径得到二项分布，均值 np、方差 np(1−p)。n 增大时它贴近同均值同标准差的正态曲线，连续性修正补上离散与连续的缝隙。","en":"Counting paths in Pascal's triangle gives the binomial with mean np and variance np(1−p). As n grows it hugs the normal curve of the same mean and spread, with a continuity correction bridging the discrete-to-continuous gap."},"source":"../binomial-normal/#step3","lesson":"binomial-normal","stage":"senior","group":"measurement"},
    {"id":"q-blackbody-radiation-0","question":{"zh":"为什么经典物理需要量子？","en":"Why did classical physics need the quantum?"},"chain":["blackbody-radiation","photoelectric-effect"],"target":{"node":"blackbody-radiation","href":"../blackbody-radiation/#step5"},"prompts":[{"node":"blackbody-radiation","ask":{"zh":"经典理论预言黑体在短波处辐射无限大——实际测到的光谱在短波处是发散还是收敛？","en":"Classical theory predicted infinite radiation at short wavelengths — does the measured spectrum diverge or converge there?"}},{"node":"photoelectric-effect","ask":{"zh":"普朗克假设能量一份一份是 hν——这个假设怎样让短波部分的辐射不再发散？","en":"Planck assumed energy comes in chunks of hν — how does that stop the short-wave radiation from diverging?"}}],"reveal":{"zh":"经典理论在短波发散（紫外灾难），与实测不符；普朗克的能量量子 hν 让高频模式难以激发，光谱收敛，量子就此登场。","en":"Classical theory diverged at short wavelengths — the ultraviolet catastrophe — contradicting measurement; Planck's energy quanta hν make high-frequency modes hard to excite, so the spectrum converges, and the quantum was born."},"source":"../blackbody-radiation/#step5","lesson":"blackbody-radiation","stage":"senior","group":"circuits"},
    {"id":"q-carbon-cycle-0","question":{"zh":"为什么停止排放后二氧化碳降得很慢？","en":"Why does CO₂ fall so slowly after emissions stop?"},"chain":["carbon-cycle","climate-energy"],"target":{"node":"carbon-cycle","href":"../carbon-cycle/#step2"},"prompts":[{"node":"carbon-cycle","ask":{"zh":"五个碳库之间流量平衡时，大气里的碳为什么还会累积？停排后碳去了哪？","en":"When flows between the five reservoirs balance, why does carbon in the air still accumulate? After emissions stop, where does the carbon go?"}},{"node":"climate-energy","ask":{"zh":"大气二氧化碳怎样变成温室效应？能量收支失衡是什么意思？","en":"How does atmospheric CO₂ become a greenhouse effect? What does an energy-budget imbalance mean?"}}],"reveal":{"zh":"五库账本里自然流量本可平衡，但排放不断加进大气，碳的去向守恒决定了它不会凭空消失。停排后多余的碳只能慢慢分流到海洋与陆地，所以大气浓度下降缓慢。","en":"In the five-reservoir ledger natural flows could balance, but emissions keep adding to the air, and conservation of where the carbon goes means it cannot vanish. After emissions stop the excess only slowly drains into ocean and land, so the air's concentration falls slowly."},"source":"../carbon-cycle/#step2","lesson":"carbon-cycle","stage":"senior","group":"earth"},
    {"id":"q-compound-interest-0","question":{"zh":"为什么越早开始存钱越划算？","en":"Why is it so much better to start saving early?"},"chain":["compound-interest","montecarlo"],"target":{"node":"compound-interest","href":"../compound-interest/#step1"},"prompts":[{"node":"compound-interest","ask":{"zh":"利息也生利息，钱是按加法长还是按倍数长？同样利率，早 10 年和晚 10 年差多少个翻倍周期？","en":"Interest earning interest — does money grow by addition or by multiples? At the same rate, how many doubling periods does starting 10 years earlier buy?"}},{"node":"montecarlo","ask":{"zh":"如果用随机模拟算很多条未来路径，早开始的优势是每次都出现，还是只在平均意义上？","en":"If you simulate many random future paths, does the early starter's advantage show up every time, or only on average?"}}],"reveal":{"zh":"复利按倍数增长 A = P(1+r)ᵗ，时间在指数上，早开始多滚几轮，差距是指数级的；翻倍时间约 72/r 年。","en":"Compound growth multiplies, A = P(1+r)ᵗ, with time in the exponent — starting earlier adds compounding rounds and the gap grows exponentially; doubling takes about 72/r years."},"source":"../compound-interest/#step1","lesson":"compound-interest","stage":"senior","group":"math"},
    {"id":"q-conic-sections-0","question":{"zh":"圆、椭圆、抛物线、双曲线是什么关系？","en":"How are the circle, ellipse, parabola and hyperbola related?"},"chain":["conic-sections","eigen"],"target":{"node":"conic-sections","href":"../conic-sections/#step1"},"prompts":[{"node":"conic-sections","ask":{"zh":"平面切圆锥，切的角度不同，截线怎样从圆变到椭圆、抛物线、双曲线？","en":"Cut a cone with a plane at different angles — how does the section change from circle to ellipse to parabola to hyperbola?"}},{"node":"eigen","ask":{"zh":"离心率 e 是到焦点与到准线距离之比——e = 0、e < 1、e = 1、e > 1 各对应哪种曲线？","en":"Eccentricity e is the ratio of distance to focus over distance to directrix — which curve goes with e = 0, e < 1, e = 1, e > 1?"}}],"reveal":{"zh":"它们是同一族曲线：平面切圆锥的角度不同而已，离心率 e 统一定义了四种类型；椭圆距离和、双曲线距离差为定值。","en":"They are one family: the same cone cut at different angles, unified by eccentricity e; an ellipse has constant sum of distances, a hyperbola constant difference."},"source":"../conic-sections/#step1","lesson":"conic-sections","stage":"senior","group":"math"},
    {"id":"q-counting-permutations-0","question":{"zh":"怎样不靠猜，数出一个概率？","en":"How do you get a probability by counting, not guessing?"},"chain":["counting-permutations","probability","bayes"],"target":{"node":"counting-permutations","href":"../counting-permutations/#step3"},"prompts":[{"node":"counting-permutations","ask":{"zh":"分步相乘：每步的选择数相乘得到什么？顺序不算数时为什么要除以 k!？","en":"Multiply the choices at each step — what does that give? When order does not matter, why divide by k!?"}},{"node":"probability","ask":{"zh":"等可能时概率 = 符合的方法数 ÷ 总方法数——生日问题里，分子分母各是什么？","en":"With equally likely outcomes, probability = matching counts ÷ total counts — in the birthday problem, what are the numerator and denominator?"}},{"node":"bayes","ask":{"zh":"数出概率后，新证据出现时怎样更新？贝叶斯更新改变的是分子还是分母？","en":"Once you have counted a probability, how does new evidence update it? Does Bayes change the numerator or the denominator?"}}],"reveal":{"zh":"分步相乘数出全部方法，符合条件的方法除以总数就是概率；新证据用贝叶斯规则更新，不用重猜。","en":"Multiply step by step to count all outcomes, divide the matching ones by the total for the probability; new evidence updates it by Bayes' rule, no guessing needed."},"source":"../counting-permutations/#step3","lesson":"counting-permutations","stage":"senior","group":"math"},
    {"id":"q-dna-replication-0","question":{"zh":"基因里的信息怎样变成蛋白质？","en":"How does the information in a gene become a protein?"},"chain":["probability","dna-replication"],"target":{"node":"dna-replication","href":"../dna-replication/#step3"},"prompts":[{"node":"probability","ask":{"zh":"碱基配对保证复制时新链和旧链互补——半保留复制是什么意思？子代 DNA 里旧链占几条？","en":"Base pairing makes each new strand complement the old — what does semi-conservative replication mean? How many old strands does each daughter DNA carry?"}},{"node":"dna-replication","ask":{"zh":"转录和翻译各把信息从什么变成什么？点突变改变的是碱基还是整个基因？","en":"Transcription and translation each convert information from what into what? Does a point mutation change a base or a whole gene?"}}],"reveal":{"zh":"DNA 半保留复制传下信息，转录成 RNA、翻译成蛋白质；点突变只改一个碱基，就可能改变一个氨基酸。","en":"DNA copies semi-conservatively to pass information on, transcribes it to RNA and translates it into protein; a point mutation changes a single base, which can change one amino acid."},"source":"../dna-replication/#step3","lesson":"dna-replication","stage":"senior","group":"systems"},
    {"id":"q-doppler-effect-0","question":{"zh":"为什么救护车驶过音调会变？","en":"Why does an ambulance change pitch as it passes?"},"chain":["superposition","doppler-effect","spectrum"],"target":{"node":"doppler-effect","href":"../doppler-effect/#step2"},"prompts":[{"node":"superposition","ask":{"zh":"运动声源的波前被挤密或拉疏——声源靠近你时，波前挤密会让频率变高还是变低？","en":"A moving source bunches or stretches its wavefronts — as it approaches you, does bunching raise or lower the frequency?"}},{"node":"doppler-effect","ask":{"zh":"救护车掠过你身边的一刻，听到的频率怎样跳变？掠过曲线在前后各是什么样？","en":"At the moment the ambulance sweeps past you, how does the heard frequency jump? What does the pass-by curve look like before and after?"}},{"node":"spectrum","ask":{"zh":"把声音按频率展开成谱——靠近和远离时，谱峰往哪个方向移？","en":"Spread the sound out by frequency into a spectrum — which way does the peak shift on approach and on retreat?"}}],"reveal":{"zh":"靠近时波前挤密、频率变高，远离时拉疏、频率变低，掠过瞬间音调跳变；这就是多普勒效应。","en":"Approaching bunches the wavefronts and raises the frequency, retreating stretches them and lowers it, with a jump as it passes — the Doppler effect."},"source":"../doppler-effect/#step2","lesson":"doppler-effect","stage":"senior","group":"waves"},
    {"id":"q-electric-fields-0","question":{"zh":"怎样把看不见的力画成图？","en":"How do you draw an invisible force?"},"chain":["vectors","electric-fields","superposition"],"target":{"node":"electric-fields","href":"../electric-fields/#step2"},"prompts":[{"node":"vectors","ask":{"zh":"力是矢量，有大小有方向——画电场时，箭头的方向和长短各表示什么？","en":"Force is a vector with size and direction — when drawing an electric field, what do an arrow's direction and length each show?"}},{"node":"electric-fields","ask":{"zh":"两个点电荷的场怎样叠加？某一点的总场是两个场的和还是差？","en":"How do two point charges' fields combine? At any point, is the total field the sum or the difference of the two?"}},{"node":"superposition","ask":{"zh":"场线和等势线有什么关系？试探电荷放上去会往哪个方向动？","en":"How do field lines relate to equipotential lines? Which way would a released test charge move?"}}],"reveal":{"zh":"用带箭头的场线画电场：方向是正试探电荷受力方向，疏密是强弱；多电荷的场按矢量叠加。","en":"Draw the field with arrows: direction is the force on a positive test charge, density is strength; multiple charges' fields add as vectors."},"source":"../electric-fields/#step2","lesson":"electric-fields","stage":"senior","group":"circuits"},
    {"id":"q-electrochemistry-0","question":{"zh":"电池为什么有电压，用着用着为什么变低？","en":"Why does a battery have a voltage, and why does it sag with use?"},"chain":["electric-fields","electrochemistry","electromagnetic-induction"],"target":{"node":"electrochemistry","href":"../electrochemistry/#step2"},"prompts":[{"node":"electric-fields","ask":{"zh":"标准电极电势不同，两个电极接起来为什么会有电压？电压由什么决定？","en":"With different standard electrode potentials, why does joining two electrodes give a voltage? What sets its size?"}},{"node":"electrochemistry","ask":{"zh":"放电时反应物消耗、产物积累——能斯特方程说，浓度变化会让电压升高还是降低？","en":"As discharge consumes reactants and builds up products, does the Nernst equation say the voltage rises or falls?"}},{"node":"electromagnetic-induction","ask":{"zh":"电解和电池放电是互逆过程——充电时外加电压要克服什么？和电磁感应里的能量转换有什么相通处？","en":"Electrolysis reverses battery discharge — what must the charging voltage overcome? What does that share with energy conversion in electromagnetic induction?"}}],"reveal":{"zh":"两电极电势差就是电压；用着用着反应物减少、产物增多，按能斯特方程电压逐渐降低。","en":"The voltage is the difference of the two electrode potentials; as reactants are used up and products build, the Nernst equation drops the voltage."},"source":"../electrochemistry/#step2","lesson":"electrochemistry","stage":"senior","group":"circuits"},
    {"id":"q-electromagnetic-induction-0","question":{"zh":"变化的磁场怎样变成电压？","en":"How does a changing magnetic field become a voltage?"},"chain":["derivative","electromagnetic-induction","oscillation"],"target":{"node":"electromagnetic-induction","href":"../electromagnetic-induction/#step1"},"prompts":[{"node":"derivative","ask":{"zh":"磁通量变化率就是电压——磁通量变化越快，电压越大还是越小？这和导数有什么关系？","en":"The rate of change of flux is the voltage — faster flux change means bigger or smaller voltage? What does that have to do with a derivative?"}},{"node":"electromagnetic-induction","ask":{"zh":"楞次定律说感应电流总要反抗变化——线圈转动发电时，感应电流的方向什么时候反向？","en":"Lenz's law says the induced current always opposes the change — in a spinning-coil generator, when does the induced current reverse direction?"}},{"node":"oscillation","ask":{"zh":"线圈匀速转动，感应电压随时间是什么形状？为什么是振荡的？","en":"A coil spinning steadily — what shape is the induced voltage over time? Why does it oscillate?"}}],"reveal":{"zh":"法拉第定律：电压等于磁通量变化率；楞次定律定方向——总反抗变化；线圈转动使磁通量周期变化，电压就是交流。","en":"Faraday's law: voltage equals the rate of change of flux; Lenz's law sets the direction — always opposing the change; a spinning coil makes the flux vary periodically, so the voltage alternates."},"source":"../electromagnetic-induction/#step1","lesson":"electromagnetic-induction","stage":"senior","group":"circuits"},
    {"id":"q-enzymes-0","question":{"zh":"为什么酶也会“忙不过来”？","en":"Why can an enzyme get \"too busy\"?"},"chain":["activation-energy","enzymes","feedback"],"target":{"node":"enzymes","href":"../enzymes/#step1"},"prompts":[{"node":"activation-energy","ask":{"zh":"酶降低活化能——底物浓度很低时，反应速率由什么限制？浓度高了呢？","en":"Enzymes lower the activation energy — at very low substrate concentration, what limits the rate? And at high concentration?"}},{"node":"enzymes","ask":{"zh":"米氏饱和曲线为什么会饱和？所有酶分子都被占满时，再加底物还有用吗？","en":"Why does the Michaelis–Menten curve level off? Once every enzyme is occupied, does adding more substrate help?"}},{"node":"feedback","ask":{"zh":"产物积累会反过来抑制酶吗？这种反馈对细胞有什么好处？","en":"Can accumulating product feed back to slow the enzyme? What good does that feedback do the cell?"}}],"reveal":{"zh":"酶分子数量有限，底物多了酶全被占满，速率就饱和了；产物反馈抑制还能自动调节快慢。","en":"Enzyme molecules are limited; with plenty of substrate they are all busy and the rate saturates; product feedback inhibition then regulates the pace automatically."},"source":"../enzymes/#step1","lesson":"enzymes","stage":"senior","group":"systems"},
    {"id":"q-expected-value-0","question":{"zh":"一个有风险的选择，怎样算值不值？","en":"How do you judge whether a risky choice is worth it?"},"chain":["expected-value","probability","variance"],"target":{"node":"expected-value","href":"../expected-value/#step1"},"prompts":[{"node":"expected-value","ask":{"zh":"期望 E = Σ p·x 算的是什么？净期望（期望 − 价格）怎样判断下注值不值？","en":"What does E = Σ p·x compute? How does net expectation (expectation minus price) judge whether a bet is worth it?"}},{"node":"probability","ask":{"zh":"长期平均为什么是“公平价”？单次结果和长期平均有什么不同？","en":"Why is the long-run average a “fair price”? How does a single outcome differ from the long-run average?"}},{"node":"variance","ask":{"zh":"只看期望会漏掉什么？为什么保险愿意用较差的期望换取更小的波动？","en":"What do you miss if you look only at expectation? Why would insurance trade a worse expectation for a smaller spread?"}}],"reveal":{"zh":"期望是长期平均的公平价，净期望等于期望减价格，E[X+Y] = E[X] + E[Y] 可以直接相加。但期望之外还要看波动，保险正是用较差的期望换取更小的波动。","en":"Expectation is the fair price of a long-run average, net expectation is expectation minus price, and E[X+Y] = E[X] + E[Y] adds directly. But beyond the mean you must also watch the spread — insurance trades a worse expectation for a smaller one."},"source":"../expected-value/#step1","lesson":"expected-value","stage":"senior","group":"math"},
    {"id":"q-gravity-orbits-0","question":{"zh":"为什么卫星不会掉下来？","en":"Why don’t satellites fall down?"},"chain":["gravity-orbits","net-force","work-energy"],"target":{"node":"gravity-orbits","href":"../gravity-orbits/#step4"},"prompts":[{"node":"gravity-orbits","ask":{"zh":"横向发射速度决定轨道——速度低于圆速度、等于、高于时，轨道各是什么形状？","en":"Sideways launch speed decides the orbit — below, equal to, and above the circular speed, what shape is each orbit?"}},{"node":"net-force","ask":{"zh":"卫星一直受引力拉向地球，为什么不掉下来？合力在做什么？","en":"Gravity keeps pulling the satellite toward Earth, so why doesn't it fall? What is the net force doing?"}},{"node":"work-energy","ask":{"zh":"能量和角动量守恒给出近远点和等面积定律——卫星离地球近时速度快还是慢？","en":"Energy and angular momentum conservation give the near and far points and the equal-areas law — is the satellite faster near Earth or far from it?"}}],"reveal":{"zh":"卫星一直在掉，但横向速度让它掉的方向不断错开地面，绕着地球转；速度等于圆速度是圆轨道，达到 √2 倍就逃逸。","en":"The satellite is always falling, but its sideways speed keeps missing the ground, so it circles Earth; circular speed gives a circle, √2 times that escapes."},"source":"../gravity-orbits/#step4","lesson":"gravity-orbits","stage":"senior","group":"systems"},
    {"id":"q-isomers-0","question":{"zh":"同样的原子能拼出几种分子？","en":"How many different molecules can the same atoms make?"},"chain":["probability","isomers","molecular-shapes"],"target":{"node":"isomers","href":"../isomers/#step1"},"prompts":[{"node":"probability","ask":{"zh":"同一分子式可以有不同连接——数烷烃骨架时，怎样避免把同一种结构数两遍？","en":"One formula can connect in different ways — when counting alkane skeletons, how do you avoid counting the same structure twice?"}},{"node":"isomers","ask":{"zh":"醇和醚原子数相同，连接不同——官能团不同，性质会一样吗？","en":"An alcohol and an ether can share the same atoms with different connections — do different functional groups mean different properties?"}},{"node":"molecular-shapes","ask":{"zh":"顺反异构形状不同——形状不同，分子性质和作用会不同吗？","en":"Cis–trans isomers differ in shape — does a different shape mean different properties and behaviour?"}}],"reveal":{"zh":"同样的原子、不同的连接就是不同的分子；骨架、官能团、顺反形状都不同，性质也就不同，计数时要用规范形式去重。","en":"Same atoms with different connections are different molecules; skeleton, functional group and cis–trans shape all change properties, and counting needs canonical forms to avoid duplicates."},"source":"../isomers/#step1","lesson":"isomers","stage":"senior","group":"math"},
    {"id":"q-magnetic-force-0","question":{"zh":"磁场怎样让粒子转圈？","en":"How does a magnetic field make a particle circle?"},"chain":["vectors","magnetic-force","oscillation"],"target":{"node":"magnetic-force","href":"../magnetic-force/#step1"},"prompts":[{"node":"vectors","ask":{"zh":"带电粒子在磁场中受力，力的方向和速度、磁场各是什么关系？","en":"A charged particle in a magnetic field feels a force — how does its direction relate to the velocity and the field?"}},{"node":"magnetic-force","ask":{"zh":"力总垂直于速度——速度大小变吗？只改变方向的力会让粒子走什么轨迹？","en":"The force is always perpendicular to the velocity — does the speed change? What path does a force that only changes direction produce?"}},{"node":"oscillation","ask":{"zh":"粒子转圈的周期和速度有关吗？质谱仪怎样利用这一点区分粒子？","en":"Does the circling period depend on speed? How does a mass spectrometer use that to tell particles apart?"}}],"reveal":{"zh":"磁场力总垂直于速度，只改方向不改大小，粒子就做圆周运动；周期与速度无关，质谱仪按周期（实际按半径）区分不同质量。","en":"The magnetic force stays perpendicular to velocity, changing direction but not speed, so the particle circles; the period is speed-independent, and a mass spectrometer separates masses by the resulting radius."},"source":"../magnetic-force/#step1","lesson":"magnetic-force","stage":"senior","group":"circuits"},
    {"id":"q-meiosis-0","question":{"zh":"为什么同一对父母的孩子都不一样？","en":"Why are children of the same parents all different?"},"chain":["probability","meiosis","montecarlo"],"target":{"node":"meiosis","href":"../meiosis/#step2"},"prompts":[{"node":"probability","ask":{"zh":"减数分裂两次分裂、染色体随机取向——n 对染色体能组合出几种配子？","en":"Meiosis divides twice with random chromosome alignment — how many gamete combinations do n pairs give?"}},{"node":"meiosis","ask":{"zh":"交换让同源染色体互换片段——交换后，配子的组合数是变多还是变少？","en":"Crossing over swaps segments between homologous chromosomes — does that raise or lower the number of gamete combinations?"}},{"node":"montecarlo","ask":{"zh":"如果随机模拟很多次受精，孩子完全相同的概率有多大？","en":"Simulating many random fertilisations, how likely are two children to come out identical?"}}],"reveal":{"zh":"随机取向给出 2ⁿ 种配子，交换又添新组合，两个配子随机结合，孩子几乎不可能完全相同。","en":"Random alignment gives 2ⁿ gametes, crossing over adds more combinations, and two random gametes combining make identical children vanishingly unlikely."},"source":"../meiosis/#step2","lesson":"meiosis","stage":"senior","group":"measurement"},
    {"id":"q-molecular-shapes-0","question":{"zh":"水为什么是弯的？","en":"Why is water bent?"},"chain":["electric-fields","molecular-shapes","derivative"],"target":{"node":"molecular-shapes","href":"../molecular-shapes/#step0"},"prompts":[{"node":"electric-fields","ask":{"zh":"价层电子对互相排斥——N 个区域怎样排布才最散？孤对为什么“更胖”？","en":"Valence electron pairs repel each other — how do N regions arrange to spread out most? Why are lone pairs \"fatter\"?"}},{"node":"molecular-shapes","ask":{"zh":"水分子有两个孤对——孤对挤压成键对，键角是变大还是变小？变成多少度左右？","en":"Water has two lone pairs — do they squeeze the bonding pairs to a bigger or smaller angle? About how many degrees?"}},{"node":"derivative","ask":{"zh":"形状不对称，水分子就有极性——极性和键角有什么关系？","en":"Water's lopsided shape gives it polarity — how is polarity tied to the bond angle?"}}],"reveal":{"zh":"电子对互斥让四个区域排成四面体，两个孤对更胖、挤压成键对，水就弯成约 104.5°，不对称的形状带来极性。","en":"Repulsion arranges four regions tetrahedrally; the two fatter lone pairs squeeze the bonding pairs, bending water to about 104.5°, and that lopsided shape makes it polar."},"source":"../molecular-shapes/#step0","lesson":"molecular-shapes","stage":"senior","group":"math"},
    {"id":"q-natural-selection-0","question":{"zh":"为什么环境一变，种群的颜色就跟着变？","en":"Why does a population's colour change when the environment does?"},"chain":["probability","natural-selection","feedback"],"target":{"node":"natural-selection","href":"../natural-selection/#step2"},"prompts":[{"node":"probability","ask":{"zh":"胡椒蛾双色模型里，存活率差异怎样一代代改变颜色比例？","en":"In the two-colour peppered-moth model, how do survival differences shift the colour ratio generation by generation?"}},{"node":"natural-selection","ask":{"zh":"优势比越大，变化越快还是越慢？环境突然反向时，种群会立刻跟上吗？","en":"The bigger the advantage ratio, the faster or slower the change? If the environment flips suddenly, does the population follow at once?"}},{"node":"feedback","ask":{"zh":"小种群里随机漂变会怎样干扰选择？反馈和漂变哪个更能决定小种群的命运？","en":"In a small population, how does random drift interfere with selection? Which matters more for a small population's fate, feedback or drift?"}}],"reveal":{"zh":"存活率高的颜色留下更多后代，比例逐代递推上升；优势比决定速度，环境变化时种群会滞后跟上。","en":"The colour that survives better leaves more offspring, so its share climbs generation by generation; the advantage ratio sets the speed, and the population lags behind a changing environment."},"source":"../natural-selection/#step2","lesson":"natural-selection","stage":"senior","group":"measurement"},
    {"id":"q-newton-laws-0","question":{"zh":"为什么推得越重加速越慢？","en":"Why does a heavier box accelerate less?"},"chain":["newton-laws","net-force"],"target":{"node":"newton-laws","href":"../newton-laws/#step2"},"prompts":[{"node":"newton-laws","ask":{"zh":"同样的合力推箱子，质量越大加速度怎样？加速度由合力和质量怎样决定？","en":"Push boxes with the same net force — the heavier the box, the bigger or smaller the acceleration? How do net force and mass set acceleration?"}},{"node":"net-force","ask":{"zh":"频闪残影里，加速度是怎样看出来的？摩擦和斜面会改变合力吗？","en":"In stroboscopic ghosts, how do you read off acceleration? Do friction and ramps change the net force?"}}],"reveal":{"zh":"a = F/m，合力相同质量越大加速度越小；摩擦和斜面都改变合力，所以加速也跟着变。","en":"a = F/m: same net force with more mass means less acceleration; friction and ramps change the net force, so acceleration changes with them."},"source":"../newton-laws/#step2","lesson":"newton-laws","stage":"senior","group":"waves"},
    {"id":"q-periodic-trends-0","question":{"zh":"为什么越往右原子越小？","en":"Why do atoms get smaller toward the right?"},"chain":["electric-fields","periodic-trends","molecular-shapes"],"target":{"node":"periodic-trends","href":"../periodic-trends/#step2"},"prompts":[{"node":"electric-fields","ask":{"zh":"同一周期从左往右，核电荷怎样变？电子层数变吗？","en":"Across a period from left to right, how does the nuclear charge change? Does the number of shells change?"}},{"node":"periodic-trends","ask":{"zh":"有效核电荷越大，对外层电子的吸引越强还是越弱？半径跟着怎样变？","en":"The larger the effective nuclear charge, the stronger or weaker the pull on outer electrons? How does the radius follow?"}},{"node":"molecular-shapes","ask":{"zh":"半径趋势和分子形状有什么关系？原子小了，成键时键长会怎样？","en":"How does the radius trend relate to molecular shape? When atoms are smaller, what happens to bond lengths?"}}],"reveal":{"zh":"同周期核电荷递增、电子层不变，有效核电荷把外层电子拉得更紧，原子半径就越往右越小。","en":"Across a period the nuclear charge rises while shells stay put, so the effective nuclear charge pulls outer electrons tighter and radii shrink toward the right."},"source":"../periodic-trends/#step2","lesson":"periodic-trends","stage":"senior","group":"math"},
    {"id":"q-probability-distribution-0","question":{"zh":"随机性为什么有形状？","en":"Why does randomness have a shape?"},"chain":["probability","probability-distribution","gaussian"],"target":{"node":"probability-distribution","href":"../probability-distribution/#step0"},"prompts":[{"node":"probability","ask":{"zh":"每个结果的概率都已知时，把它们按结果排成一排，会看到什么？","en":"When every outcome's probability is known, what do you see if you line them up by outcome?"}},{"node":"probability-distribution","ask":{"zh":"条形的高度、重心、离散程度各由什么决定？右尾的面积回答什么问题？","en":"What decides the bars' heights, balance point, and spread? What question does the right tail's area answer?"}},{"node":"gaussian","ask":{"zh":"把条形变细变多，对称分布会趋向什么形状？为什么说那是同一现象的连续表示？","en":"As the bars get finer and more numerous, what shape does a symmetric distribution tend toward, and why is that the continuous representation of the same phenomenon?"}}],"reveal":{"zh":"每个结果的概率排成条形，就是分布。条形的重心是期望，条形离重心的加权平方距离是方差。","en":"Probabilities arranged by outcome form a distribution. The bars' balance point is the expectation, and their probability-weighted squared distance from it is the variance."},"source":"../probability-distribution/#step0","lesson":"probability-distribution","stage":"senior","group":"measurement"},
    {"id":"q-projectile-circular-0","question":{"zh":"卫星为什么不会掉下来？","en":"Why doesn’t a satellite fall down?"},"chain":["net-force","projectile-circular"],"target":{"node":"projectile-circular","href":"../projectile-circular/#step4"},"prompts":[{"node":"net-force","ask":{"zh":"抛体运动可把速度分成水平和竖直两份——水平方向受力吗？竖直方向呢？","en":"Projectile motion splits velocity into horizontal and vertical parts — is there a force horizontally? Vertically?"}},{"node":"projectile-circular","ask":{"zh":"匀速圆周需要向心加速度——卫星绕地球转，向心力由什么提供？","en":"Uniform circular motion needs centripetal acceleration — for a satellite circling Earth, what supplies the centripetal force?"}}],"reveal":{"zh":"卫星水平速度约 7.9 km/s 时，下落的弧度正好跟上地球表面的弯曲，于是绕着地球转而不掉下来；11.2 km/s 就脱离。","en":"At about 7.9 km/s sideways, the satellite's fall curves exactly with Earth's surface, so it circles without landing; 11.2 km/s escapes."},"source":"../projectile-circular/#step4","lesson":"projectile-circular","stage":"senior","group":"waves"},
    {"id":"q-regression-correlation-0","question":{"zh":"怎样从一堆点里拉出最贴的直线？","en":"How do you fit the best line to a cloud of points?"},"chain":["variance","regression-correlation","slope"],"target":{"node":"regression-correlation","href":"../regression-correlation/#step1"},"prompts":[{"node":"variance","ask":{"zh":"相关系数 r 说明点云多贴一条直线——r 接近 1、接近 0 各是什么意思？","en":"Correlation r says how tightly a cloud follows a line — what do r near 1 and r near 0 each mean?"}},{"node":"regression-correlation","ask":{"zh":"最小二乘线是让残差平方和最小的线——为什么用平方和，不用残差的和？","en":"The least-squares line minimises the sum of squared residuals — why squares, not just the sum of residuals?"}},{"node":"slope","ask":{"zh":"离群点和杠杆点会把直线拉偏吗？混杂因素和非线性关系会怎样误导解读？","en":"Can outliers and leverage points drag the line off? How do confounders and nonlinear relations mislead the reading?"}}],"reveal":{"zh":"r 度量贴合程度，最小二乘找残差平方和最小的线；但离群点、杠杆、混杂和非线性都会让直线误导，解读时要先看点云。","en":"r measures the fit, least squares finds the line minimising squared residuals — but outliers, leverage, confounders and nonlinearity can all mislead, so look at the cloud first."},"source":"../regression-correlation/#step1","lesson":"regression-correlation","stage":"senior","group":"measurement"},
    {"id":"q-resonance-0","question":{"zh":"为什么推秋千要踩中节拍？","en":"Why must you push a swing in time?"},"chain":["oscillation","resonance","freqresp"],"target":{"node":"resonance","href":"../resonance/#step3"},"prompts":[{"node":"oscillation","ask":{"zh":"秋千有固有频率——推的节拍和固有频率一致时，每次推动是加能量还是减能量？","en":"A swing has a natural frequency — when your pushes match it, does each push add energy or remove it?"}},{"node":"resonance","ask":{"zh":"阻尼比决定共振曲线多尖——阻尼大时，推偏一点节拍还能推起来吗？","en":"The damping ratio sets how sharp the resonance curve is — with heavy damping, can you still build up the swing pushing slightly off-beat?"}},{"node":"freqresp","ask":{"zh":"稳态振幅最大时，相位滞后是多少？推力和运动是什么关系？","en":"At maximum steady-state amplitude, what is the phase lag? How do push and motion relate?"}}],"reveal":{"zh":"踩中固有频率，每次推动都顺着运动加能量，振幅越推越大；节拍偏了，能量时加时减，推不起来。","en":"Push at the natural frequency and every push feeds energy in phase, so amplitude builds; off-beat, energy alternately adds and cancels, and the swing never builds up."},"source":"../resonance/#step3","lesson":"resonance","stage":"senior","group":"waves"},
    {"id":"q-seismic-waves-0","question":{"zh":"没人到过地核，怎么知道它是液体？","en":"No one has been to the core, so how do we know it is liquid?"},"chain":["snell","seismic-waves"],"target":{"node":"seismic-waves","href":"../seismic-waves/#step3"},"prompts":[{"node":"snell","ask":{"zh":"P 波快、S 波慢——用 S−P 时间能估出震中距，为什么还需要三个台站才能定位？","en":"P is fast and S is slow — S−P time estimates the epicentre distance, so why do you need three stations to locate it?"}},{"node":"seismic-waves","ask":{"zh":"S 波被液态外核挡住——如果外核是固态，S 波会怎样？P 波影区又说明什么？","en":"S waves are blocked by the liquid outer core — if it were solid, what would S waves do? And what does the P-wave shadow zone tell us?"}}],"reveal":{"zh":"S 波穿不过液态外核、P 波有影区，波线弯曲和影区位置合起来说明外核是液体；没人下去也能从波里读出地球内部。","en":"S waves cannot cross a liquid outer core and P waves leave a shadow zone; the bending rays and shadow pattern together say the outer core is liquid — Earth's interior read from waves alone."},"source":"../seismic-waves/#step3","lesson":"seismic-waves","stage":"senior","group":"waves"},
    {"id":"q-sequences-series-0","question":{"zh":"无穷多项相加为什么能有结果？","en":"How can infinitely many terms add up to something?"},"chain":["slope","sequences-series","integral"],"target":{"node":"sequences-series","href":"../sequences-series/#step1"},"prompts":[{"node":"slope","ask":{"zh":"等差数列倒序相加是把两列拼成长方形——这个办法为什么能一次算出前 n 项和？","en":"Adding an arithmetic series backwards pairs two rows into a rectangle — why does that give the sum of the first n terms at once?"}},{"node":"sequences-series","ask":{"zh":"等比数列 |r|<1 时部分和趋近极限——公比小于 1 时，后面的项是变大还是变小？小到什么程度？","en":"For a geometric series with |r| < 1 the partial sums approach a limit — with ratio below 1, do later terms grow or shrink? How small do they get?"}},{"node":"integral","ask":{"zh":"无穷项求和与积分有什么相通处？线性累计和指数累计的反超说明了什么？","en":"What does summing infinitely many terms share with integration? What does linear versus exponential accumulation overtaking tell us?"}}],"reveal":{"zh":"|r|<1 时后面的项趋近于 0，部分和收敛到有限值；等比增长最终会反超线性增长，这就是无穷求和有结果的道理。","en":"With |r| < 1 later terms shrink toward zero and partial sums converge to a finite value; exponential growth eventually overtakes linear growth — that is how infinitely many terms can add up to something."},"source":"../sequences-series/#step1","lesson":"sequences-series","stage":"senior","group":"math"},
    {"id":"q-titration-curves-0","question":{"zh":"怎样判断滴定终点？","en":"How do you decide where a titration ends?"},"chain":["derivative","titration-curves","estimate"],"target":{"node":"titration-curves","href":"../titration-curves/#step2"},"prompts":[{"node":"derivative","ask":{"zh":"突跃处斜率最大是什么意思？为什么斜率最大的点就是终点附近？","en":"What does it mean that the slope peaks at the leap? Why is the steepest point near the end point?"}},{"node":"titration-curves","ask":{"zh":"强酸和弱酸的曲线、突跃、半等当点有什么不同？指示剂按什么选？","en":"How do strong-acid and weak-acid curves, leaps and half-equivalence points differ? How is an indicator chosen?"}},{"node":"estimate","ask":{"zh":"终点读数怎样变成浓度估计？这个估计的不确定度来自哪里？","en":"How does an end-point reading become a concentration estimate? Where does that estimate's uncertainty come from?"}}],"reveal":{"zh":"强酸、弱酸被强碱滴定的 pH 曲线各有突跃与半等当点，突跃就是斜率最大处。用终点读数估算浓度，指示剂要选在突跃区间内变色。","en":"pH curves for strong and weak acids titrated by a strong base each have a leap and a half-equivalence point, and the leap is where the slope peaks. The end-point reading estimates the concentration, and the indicator must change colour inside the leap's interval."},"source":"../titration-curves/#step2","lesson":"titration-curves","stage":"senior","group":"measurement"},
    {"id":"q-vectors-0","question":{"zh":"几个力合在一起怎么算？","en":"How do several forces combine?"},"chain":["vectors","net-force"],"target":{"node":"vectors","href":"../vectors/#step1"},"prompts":[{"node":"vectors","ask":{"zh":"向量加法首尾相接——两个力方向相同、相反时，合力各是多少？","en":"Vector addition joins arrows head to tail — for two forces in the same direction, and in opposite directions, what is each resultant?"}},{"node":"net-force","ask":{"zh":"绳子受力平衡时，几个力的合力是多少？合力为零意味着什么？","en":"When rope forces balance, what is their resultant? What does a zero resultant mean?"}}],"reveal":{"zh":"力按矢量相加：首尾相接画箭头，合力是起点到终点的箭头；合力为零就是平衡。","en":"Forces add as vectors: join arrows head to tail and the resultant runs from start to finish; a zero resultant is balance."},"source":"../vectors/#step1","lesson":"vectors","stage":"senior","group":"math"},
    {"id":"q-attention-mechanism-0","question":{"zh":"一个词怎样决定看谁？","en":"How does a word decide whom to look at?"},"chain":["vectors","attention-mechanism","probability"],"target":{"node":"attention-mechanism","href":"../attention-mechanism/#step2"},"prompts":[{"node":"vectors","ask":{"zh":"查询与键的点积给出分数——点积大是什么意思？两个向量越像，分数越高还是越低？","en":"Query-key dot products give scores — what does a big dot product mean? The more alike two vectors are, the higher or lower the score?"}},{"node":"attention-mechanism","ask":{"zh":"softmax 把分数变成权重——权重加起来是多少？权重最大的词对输出影响最大吗？","en":"Softmax turns scores into weights — what do the weights add up to? Does the highest-weight word influence the output most?"}},{"node":"probability","ask":{"zh":"对值向量加权求和得到输出——权重为零的词对输出有贡献吗？","en":"A weighted sum of value vectors gives the output — does a zero-weight word contribute anything?"}}],"reveal":{"zh":"点积度量查询与键的相似，softmax 转成和为 1 的权重，输出就是值向量的加权平均——权重大的词主导了输出。","en":"The dot product measures query-key similarity, softmax turns it into weights summing to 1, and the output is the weighted average of value vectors — high-weight words dominate it."},"source":"../attention-mechanism/#step2","lesson":"attention-mechanism","stage":"university","group":"systems"},
    {"id":"q-backpropagation-0","question":{"zh":"误差怎样回到每个权重？","en":"How does the error get back to every weight?"},"chain":["derivative","backpropagation","gradient-descent"],"target":{"node":"backpropagation","href":"../backpropagation/#step2"},"prompts":[{"node":"derivative","ask":{"zh":"斜率在这里量的是什么？损失对某个权重的斜率告诉你什么？","en":"What does a slope measure here? What does the slope of the loss with respect to one weight tell you?"}},{"node":"backpropagation","ask":{"zh":"链式法则怎样把输出端的责任一路乘回每个权重？为什么一次向后扫描就够了？","en":"How does the chain rule multiply the output's blame all the way back to every weight? Why is one backward sweep enough?"}},{"node":"gradient-descent","ask":{"zh":"梯度到手后，权重往哪个方向走一小步？步子太大或太小会怎样？","en":"Once you have the gradient, which way does each weight take a small step? What goes wrong if the step is too big or too small?"}}],"reveal":{"zh":"链式法则把损失的责任从输出一路往回乘到每个权重，一次向后扫描就得到全部梯度，不用逐个权重扰动试错。梯度到手后，权重沿着使损失减小的方向走一小步，这就是梯度下降。","en":"The chain rule multiplies the loss's blame backwards from the output to every weight, so one backward sweep yields all gradients instead of perturbing each weight one by one. With gradients in hand, each weight takes a small step in the direction that reduces the loss — that is gradient descent."},"source":"../backpropagation/#step2","lesson":"backpropagation","stage":"university","group":"systems"},
    {"id":"q-bandit-arms-0","question":{"zh":"信息不全时怎样在尝试和利用之间取舍？","en":"How to trade off trying and exploiting with incomplete information?"},"chain":["montecarlo","bandit-arms","bayes"],"target":{"node":"bandit-arms","href":"../bandit-arms/#step2"},"prompts":[{"node":"montecarlo","ask":{"zh":"概率未知的几台机器——只拉目前最好的（贪心），会错过什么？","en":"With machines of unknown probability — pulling only the current best (greedy), what do you miss?"}},{"node":"bandit-arms","ask":{"zh":"ε-贪心、UCB、汤普森采样各怎样在尝试和利用之间分配拉动次数？","en":"How do ε-greedy, UCB and Thompson sampling each split pulls between trying and exploiting?"}},{"node":"bayes","ask":{"zh":"每拉一次都得到新信息——贝叶斯更新怎样改变你对每台机器的判断？","en":"Every pull brings new information — how does Bayesian updating change your judgement of each machine?"}}],"reveal":{"zh":"纯贪心会困在局部最优；UCB 给不确定性高的机器加分、汤普森采样按后验概率选，累计遗憾都比纯贪心低。","en":"Pure greed gets stuck at a local best; UCB bonuses uncertain machines and Thompson sampling draws by posterior probability, and both rack up less cumulative regret than pure greed."},"source":"../bandit-arms/#step2","lesson":"bandit-arms","stage":"university","group":"measurement"},
    {"id":"q-carnot-cycle-0","question":{"zh":"热机的效率为什么有上限？","en":"Why is there a ceiling on heat-engine efficiency?"},"chain":["carnot-cycle","work-energy"],"target":{"node":"carnot-cycle","href":"../carnot-cycle/#step4"},"prompts":[{"node":"carnot-cycle","ask":{"zh":"p–V 图上回路围出的面积是什么？净功和吸热、放热什么关系？","en":"On a p–V diagram, what is the area enclosed by the loop? How do net work, heat in and heat out relate?"}},{"node":"work-energy","ask":{"zh":"效率上限 1 − T_c/T_h 由什么决定？提高热源温度还是降低冷源温度更有效？","en":"What sets the efficiency ceiling 1 − T_c/T_h? Is raising the hot temperature or lowering the cold one more effective?"}}],"reveal":{"zh":"净功就是回路面积，Q_h = W + Q_c；可逆循环的效率只由两端温度定，1 − T_c/T_h 是任何热机都越不过的上限。","en":"Net work is the enclosed area, with Q_h = W + Q_c; a reversible cycle's efficiency depends only on the two temperatures, and 1 − T_c/T_h is a ceiling no heat engine can pass."},"source":"../carnot-cycle/#step4","lesson":"carnot-cycle","stage":"university","group":"circuits"},
    {"id":"q-chaos-threebody-0","question":{"zh":"为什么天气只能预报几天？","en":"Why can weather be forecast only a few days ahead?"},"chain":["chaos-threebody","feedback"],"target":{"node":"chaos-threebody","href":"../chaos-threebody/#step3"},"prompts":[{"node":"chaos-threebody","ask":{"zh":"确定的规则也能产生无法长期预测的行为——初始误差按 e^{λt} 放大，λ > 0 意味着什么？","en":"Deterministic rules can still be unpredictable long term — initial errors grow like e^{λt}; what does λ > 0 mean?"}},{"node":"feedback","ask":{"zh":"可预测期限只与精度的对数成正比——观测精度提高 10 倍，预报期限延长几倍还是只延长一点？","en":"The predictable horizon grows only with the logarithm of precision — improve observations tenfold, and does the horizon stretch several times or just a little?"}}],"reveal":{"zh":"误差指数放大，精度提高 10 倍也只把可预测期限延长一个常数；洛伦兹吸引子与三体 8 字轨道都是确定规则、长期不可预测的例子。","en":"Errors grow exponentially, so tenfold better precision only extends the horizon by a constant; the Lorenz attractor and the three-body figure-eight are deterministic yet unpredictable long term."},"source":"../chaos-threebody/#step3","lesson":"chaos-threebody","stage":"university","group":"systems"},
    {"id":"q-cnn-feature-maps-0","question":{"zh":"卷积神经网络是怎么“看”图的？","en":"How does a convolutional network “see” a picture?"},"chain":["cnn-feature-maps","convolution","derivative"],"target":{"node":"cnn-feature-maps","href":"../cnn-feature-maps/#step0"},"prompts":[{"node":"cnn-feature-maps","ask":{"zh":"3×3 核在图像上滑动时，每一步算的是什么？不同的核为什么响应不同的边缘？","en":"As a 3×3 kernel slides over an image, what does each step compute? Why do different kernels respond to different edges?"}},{"node":"convolution","ask":{"zh":"一维滑动求和怎样推广到二维图像？权重在这里是什么意思？","en":"How does a one-dimensional sliding sum extend to two-dimensional images? What do the weights mean here?"}},{"node":"derivative","ask":{"zh":"边缘核算出的差分和导数有什么关系？为什么差分大的地方就是边缘？","en":"How do the differences an edge kernel computes relate to derivatives? Why is a place with big differences an edge?"}}],"reveal":{"zh":"3×3 卷积核在图像上滑动、对应相乘求和得到特征图，不同的核响应不同的边缘。边缘核算的是差分、近似导数，ReLU、池化与堆叠再把边缘拼成更复杂的特征，核也可以由梯度下降学出。","en":"A 3×3 kernel slides over an image, multiplying and summing to give a feature map, and different kernels respond to different edges. Edge kernels compute differences that approximate derivatives, and ReLU, pooling and stacking assemble edges into richer features, with kernels learnable by gradient descent."},"source":"../cnn-feature-maps/#step0","lesson":"cnn-feature-maps","stage":"university","group":"computing"},
    {"id":"q-decision-trees-0","question":{"zh":"怎样用最少的问题把两类分开？","en":"How can two classes be separated with the fewest questions?"},"chain":["probability","decision-trees"],"target":{"node":"decision-trees","href":"../decision-trees/#step1"},"prompts":[{"node":"probability","ask":{"zh":"熵衡量混乱——一刀切下去，怎样算这一刀好不好？","en":"Entropy measures disorder — after one cut, how do you judge whether it was a good cut?"}},{"node":"decision-trees","ask":{"zh":"按信息增益挑每一刀，贪心地长树——贪心保证全局最少问题吗？","en":"Picking each cut by information gain grows the tree greedily — does greed guarantee the fewest questions overall?"}}],"reveal":{"zh":"每刀选信息增益最大的切法，混乱下降最快；但贪心只看眼前一步，深度限制则是防止学到噪声。","en":"Each cut picks the largest information gain, dropping disorder fastest; but greed only looks one step ahead, and depth limits stop the tree from learning noise."},"source":"../decision-trees/#step1","lesson":"decision-trees","stage":"university","group":"measurement"},
    {"id":"q-double-slit-0","question":{"zh":"为什么一个电子也会“同时”走两条缝？","en":"Why does a single electron behave as if it takes both slits?"},"chain":["double-slit","interference","superposition"],"target":{"node":"double-slit","href":"../double-slit/#step2"},"prompts":[{"node":"double-slit","ask":{"zh":"一颗颗粒子的落点怎样累积成条纹？知道走了哪条缝时条纹为什么消失？","en":"How do single particles' landing dots build up into fringes? Why do the fringes vanish once you know which slit was used?"}},{"node":"interference","ask":{"zh":"路程差怎样决定明暗？条纹间距 Δy = λL/d 里每个字母是什么意思？","en":"How does path difference decide bright and dark? In the fringe spacing Δy = λL/d, what does each letter mean?"}},{"node":"superposition","ask":{"zh":"概率幅相加和普通概率相加有什么不同？为什么“同时走两条缝”其实是振幅在相加？","en":"How does adding probability amplitudes differ from adding ordinary probabilities? Why does “taking both slits at once” really mean amplitudes adding?"}}],"reveal":{"zh":"双缝条纹间距 Δy = λL/d，被单缝 sinc² 包络罩住。一颗颗粒子的落点累积成条纹，因为概率幅按叠加相加、路程差决定明暗，而知道走了哪条缝则条纹消失。","en":"Double-slit fringes are spaced Δy = λL/d under a single-slit sinc² envelope. Single particles build the fringes dot by dot because probability amplitudes add by superposition, with path difference deciding bright and dark — and knowing which slit was used erases them."},"source":"../double-slit/#step2","lesson":"double-slit","stage":"university","group":"waves"},
    {"id":"q-embeddings-0","question":{"zh":"词怎样变成可计算的向量？","en":"How does a word become a computable vector?"},"chain":["vectors","embeddings","attention-mechanism"],"target":{"node":"embeddings","href":"../embeddings/#step1"},"prompts":[{"node":"vectors","ask":{"zh":"词表示成一列数——余弦衡量相似，余弦接近 1 说明什么？","en":"Words become lists of numbers — cosine measures similarity; what does a cosine near 1 say?"}},{"node":"embeddings","ask":{"zh":"向量加减做类比——“国王 − 男人 + 女人”会指向什么？","en":"Vector arithmetic solves analogies — what does “king − man + woman” point at?"}},{"node":"attention-mechanism","ask":{"zh":"从共现统计里学出向量——经常一起出现的词，向量会靠近还是远离？","en":"Vectors are learned from co-occurrence statistics — do words that often appear together end up closer or farther apart?"}}],"reveal":{"zh":"共现统计把词变成向量，余弦度量相似、加减法做类比；注意力机制正是用这些向量算查询与键的点积。","en":"Co-occurrence statistics turn words into vectors, cosine measures similarity and arithmetic solves analogies; the attention mechanism then uses these vectors for query-key dot products."},"source":"../embeddings/#step1","lesson":"embeddings","stage":"university","group":"math"},
    {"id":"q-externalities-0","question":{"zh":"为什么污染和过度捕捞很难靠市场自己解决？","en":"Why are pollution and overfishing so hard for markets to fix by themselves?"},"chain":["externalities","supply-demand","game-theory"],"target":{"node":"externalities","href":"../externalities/#step3"},"prompts":[{"node":"externalities","ask":{"zh":"价格漏掉一部分成本时，市场会多生产还是少生产？无谓损失 ½·e·(Q_m − Q*) 里每个字母是什么意思？","en":"When the price leaves out part of the cost, does the market produce too much or too little? In the deadweight loss ½·e·(Q_m − Q*), what does each letter mean?"}},{"node":"supply-demand","ask":{"zh":"均衡价格是两边都愿意交易的交点——如果成本没进价格，这个交点还对吗？","en":"The equilibrium price is where both sides plan to trade — if the cost never entered the price, is that crossing point still right?"}},{"node":"game-theory","ask":{"zh":"公地悲剧为什么是多人博弈？每个人都理性时，为什么结果反而对大家都不好？","en":"Why is the tragedy of the commons a many-player game? When everyone is rational, why is the outcome worse for all?"}}],"reveal":{"zh":"部分成本落在第三方身上时，市场按私人成本多生产，无谓损失等于 ½·e·(Q_m − Q*)。庇古税按边际外部损害定价可使福利最大，而科斯指出无成本谈判下权利归谁不影响效率。","en":"When part of the cost falls on a third party the market over-produces on private cost, with deadweight loss ½·e·(Q_m − Q*). A Pigouvian tax equal to the marginal damage maximises welfare, and Coase notes that with costless bargaining who holds the rights does not change efficiency."},"source":"../externalities/#step3","lesson":"externalities","stage":"university","group":"math"},
    {"id":"q-gravitational-lensing-0","question":{"zh":"为什么遥远的星系会变成一个光环？","en":"Why does a distant galaxy turn into a ring of light?"},"chain":["gravitational-lensing","snell"],"target":{"node":"gravitational-lensing","href":"../gravitational-lensing/#step2"},"prompts":[{"node":"gravitational-lensing","ask":{"zh":"质量使光偏折 α = 4GM/(c²b)——质量越大、光线离得越近，偏折越大还是越小？","en":"Mass deflects light by α = 4GM/(c²b) — bigger mass, closer pass: bigger or smaller deflection?"}},{"node":"snell","ask":{"zh":"点质量透镜方程给出两个像——光源、透镜、观测者恰好在一条线上时，两个像变成什么？","en":"The point-mass lens equation gives two images — when source, lens and observer line up exactly, what do the two images become?"}}],"reveal":{"zh":"光源在连线上时，两个像连成一个环——爱因斯坦环；环的大小随透镜质量平方根增大，所以能由环称出透镜质量。","en":"With the source on the line, the two images join into a ring — an Einstein ring; its size grows with the square root of the lens mass, so the ring weighs the lens."},"source":"../gravitational-lensing/#step2","lesson":"gravitational-lensing","stage":"university","group":"waves"},
    {"id":"q-hypothesis-testing-0","question":{"zh":"“p < 0.05”到底说明了什么？","en":"What does “p < 0.05” really tell us?"},"chain":["hypothesis-testing","bayes","probability"],"target":{"node":"hypothesis-testing","href":"../hypothesis-testing/#step0"},"prompts":[{"node":"hypothesis-testing","ask":{"zh":"p 值是零假设为真时出现至少同样极端结果的概率——p = 0.03 是说零假设为真的概率是 3% 吗？","en":"The p-value is the probability, if the null is true, of a result at least as extreme — does p = 0.03 mean the null has a 3% chance of being true?"}},{"node":"bayes","ask":{"zh":"α 是第一类错误的预算——同时做多次检验，总会碰到“显著”，为什么需要校正？","en":"α is the budget for type-I errors — running many tests at once will hit “significant” by chance, so why is correction needed?"}},{"node":"probability","ask":{"zh":"p 值和贝叶斯的后验概率有什么区别？哪个直接回答“假设为真吗”？","en":"How does a p-value differ from a Bayesian posterior? Which one directly answers “is the hypothesis true?”?"}}],"reveal":{"zh":"p 值不是假设为真的概率，只是零假设下极端结果的概率；α 是犯第一类错误的预算，多次检验不校正就会假阳性泛滥。","en":"A p-value is not the probability the hypothesis is true, only the probability of an extreme result under the null; α budgets type-I errors, and uncorrected multiple testing floods you with false positives."},"source":"../hypothesis-testing/#step0","lesson":"hypothesis-testing","stage":"university","group":"measurement"},
    {"id":"q-kinetic-theory-0","question":{"zh":"压强和温度从哪里来？","en":"Where do pressure and temperature come from?"},"chain":["work-energy","kinetic-theory","probability"],"target":{"node":"kinetic-theory","href":"../kinetic-theory/#step0"},"prompts":[{"node":"work-energy","ask":{"zh":"压强是撞墙冲量——分子撞墙越猛、越频繁，压强越大还是越小？","en":"Pressure is wall impulse — harder, more frequent wall collisions: bigger or smaller pressure?"}},{"node":"kinetic-theory","ask":{"zh":"温度是平均动能——温度升高，分子的平均动能怎样变？速率分布的形状怎样变？","en":"Temperature is mean kinetic energy — as temperature rises, how does mean kinetic energy change? How does the speed distribution's shape change?"}},{"node":"probability","ask":{"zh":"碰撞怎样生成麦克斯韦速率分布？分布是事先设定的还是碰撞自然产生的？","en":"How do collisions generate the Maxwell speed distribution? Is the distribution preset, or does it emerge from collisions?"}}],"reveal":{"zh":"压强是大量分子撞墙的冲量平均，温度是平均动能；碰撞不断交换能量，自然生成麦克斯韦速率分布。","en":"Pressure is the average impulse of countless wall collisions, temperature is mean kinetic energy; collisions constantly exchange energy and the Maxwell speed distribution emerges on its own."},"source":"../kinetic-theory/#step0","lesson":"kinetic-theory","stage":"university","group":"waves"},
    {"id":"q-llm-sampling-0","question":{"zh":"模型怎样一个词一个词写出句子？","en":"How does a model write a sentence word by word?"},"chain":["probability","llm-sampling"],"target":{"node":"llm-sampling","href":"../llm-sampling/#step1"},"prompts":[{"node":"probability","ask":{"zh":"每一步把分数用 softmax 变成概率——温度整形是什么意思？温度高了，分布变平还是变尖？","en":"Each step turns scores into probabilities via softmax — what does temperature shaping do? Higher temperature: flatter or sharper distribution?"}},{"node":"llm-sampling","ask":{"zh":"top-k / top-p 截断尾巴——截断后，剩下的词是按概率随机抽，还是取概率最大的？","en":"Top-k / top-p trim the tail — after trimming, are the remaining words drawn randomly by probability, or is the most probable one taken?"}}],"reveal":{"zh":"每步先把分数变概率、温度整形、截断尾巴，再随机抽一个词；抽到的词接进上下文，下一轮重复——句子就是这样一个词一个词长出来的。","en":"Each step turns scores into probabilities, reshapes them with temperature, trims the tail, then draws one word at random; that word joins the context and the cycle repeats — sentences grow one word at a time."},"source":"../llm-sampling/#step1","lesson":"llm-sampling","stage":"university","group":"measurement"},
    {"id":"q-markov-chains-0","question":{"zh":"为什么随机游走会有稳定的长期比例？","en":"Why does a random walk have a stable long-run share?"},"chain":["markov-chains","eigen","probability"],"target":{"node":"markov-chains","href":"../markov-chains/#step3"},"prompts":[{"node":"markov-chains","ask":{"zh":"下一步只取决于当前状态时，n 步转移为什么是转移矩阵的 n 次幂？","en":"When the next step depends only on the current state, why is the n-step transition the n-th power of the transition matrix?"}},{"node":"eigen","ask":{"zh":"第二特征值 |λ₂| 怎样决定收敛速度？特征值 1 对应的方向有什么特殊含义？","en":"How does the second eigenvalue |λ₂| set the convergence speed? What is special about the direction belonging to eigenvalue 1?"}},{"node":"probability","ask":{"zh":"稳态 π（πP = π）是什么意思？长期比例和单步概率有什么不同？","en":"What does the steady state π (πP = π) mean? How does a long-run share differ from a single-step probability?"}}],"reveal":{"zh":"下一步只取决于当前状态，n 步转移是转移矩阵的 n 次幂。正常的链收敛到稳态 π（πP = π），速度由第二特征值 |λ₂| 决定，有吸收态的链没有中间稳态。","en":"The next step depends only on the current state, so n-step transitions are the n-th power of the transition matrix. An ordinary chain converges to a steady state π (πP = π) at a speed set by the second eigenvalue |λ₂|, while a chain with absorbing states has no in-between steady state."},"source":"../markov-chains/#step3","lesson":"markov-chains","stage":"university","group":"measurement"},
    {"id":"q-newton-method-0","question":{"zh":"怎样用导数更快地解方程？","en":"How can a derivative solve equations faster?"},"chain":["derivative","newton-method"],"target":{"node":"newton-method","href":"../newton-method/#step2"},"prompts":[{"node":"derivative","ask":{"zh":"用切线与横轴的交点作下一个猜测——为什么切线交点比原点更接近根？","en":"Take where the tangent meets the x-axis as the next guess — why is the tangent's crossing closer to the root than the starting point?"}},{"node":"newton-method","ask":{"zh":"正确位数大约翻倍——这比二分法快多少？切线水平、循环时又会怎样失败？","en":"Correct digits roughly double — how much faster is that than bisection? And how does it fail with a flat tangent or a cycle?"}}],"reveal":{"zh":"切线在根附近是很好的近似，交点一次比一次准、正确位数约翻倍；但切线水平、循环或起点不好时也会失败，这时二分法更稳。","en":"Near the root the tangent is a good approximation, so each crossing lands closer and correct digits roughly double; but a flat tangent, a cycle or a bad start can break it, where bisection stays steady."},"source":"../newton-method/#step2","lesson":"newton-method","stage":"university","group":"math"},
    {"id":"q-ode-phase-portraits-0","question":{"zh":"两个互相影响的种群会怎样起落？","en":"How do two interacting populations rise and fall?"},"chain":["derivative","ode-phase-portraits","eigen"],"target":{"node":"ode-phase-portraits","href":"../ode-phase-portraits/#step2"},"prompts":[{"node":"derivative","ask":{"zh":"时间曲线和相平面看的是同一件事吗？相平面上横轴纵轴各是什么？","en":"Do time curves and the phase plane show the same thing? What are the phase plane's axes?"}},{"node":"ode-phase-portraits","ask":{"zh":"零线与平衡点怎样找？平衡点附近，种群是回到平衡还是绕圈？","en":"How do you find nullclines and the equilibrium? Near equilibrium, do the populations return to it or circle around?"}},{"node":"eigen","ask":{"zh":"守恒量 H 不变意味着轨线是什么形状？加拥挤项后闭圈为什么变成螺旋？","en":"A conserved quantity H means what shape for the trajectories? Why does adding a crowding term turn closed loops into spirals?"}}],"reveal":{"zh":"相平面上轨线绕平衡点转圈，对应两个种群此起彼伏；守恒量 H 定出闭圈，加拥挤项耗散能量，闭圈收成螺旋。","en":"Trajectories circle the equilibrium in the phase plane, matching two populations rising and falling in turn; the conserved H fixes closed loops, and a crowding term dissipates energy, winding loops into spirals."},"source":"../ode-phase-portraits/#step2","lesson":"ode-phase-portraits","stage":"university","group":"systems"},
    {"id":"q-overfitting-0","question":{"zh":"为什么训练得越好，新数据反而更差？","en":"Why can better training mean worse results on new data?"},"chain":["variance","overfitting","decision-trees"],"target":{"node":"overfitting","href":"../overfitting/#step1"},"prompts":[{"node":"variance","ask":{"zh":"训练误差随灵活度单调下降——灵活度越高，训练误差越低，这能说明模型越好吗？","en":"Training error falls monotonically with flexibility — higher flexibility, lower training error: does that mean a better model?"}},{"node":"overfitting","ask":{"zh":"测试误差先降后升——转折点前后，模型分别在欠拟合还是过拟合？","en":"Test error falls then rises — before and after the turning point, is the model underfitting or overfitting?"}},{"node":"decision-trees","ask":{"zh":"决策树深度限制和岭回归各怎样压住过拟合？换批数据能看出什么？","en":"How do decision-tree depth limits and ridge regression each hold back overfitting? What does a fresh batch of data reveal?"}}],"reveal":{"zh":"灵活度太高，模型把噪声也学进去了，训练误差继续降、测试误差反而升；限制深度、加正则、换批验证都是在压住这一点。","en":"Too much flexibility lets the model learn the noise too: training error keeps falling while test error rises; depth limits, regularisation and fresh-batch validation all hold that in check."},"source":"../overfitting/#step1","lesson":"overfitting","stage":"university","group":"measurement"},
    {"id":"q-pagerank-0","question":{"zh":"谁被链接，谁就重要吗？","en":"Is a page important just because it is linked to?"},"chain":["probability","pagerank","eigen"],"target":{"node":"pagerank","href":"../pagerank/#step2"},"prompts":[{"node":"probability","ask":{"zh":"“重要”定义成随机冲浪者长期停留的概率——被很多页链接的页，停留概率一定高吗？","en":"“Important” means the long-run probability of a random surfer — does a page with many incoming links necessarily have a high stay probability?"}},{"node":"pagerank","ask":{"zh":"阻尼系数是什么意思？冲浪者为什么有时要随机跳到任意一页？","en":"What is the damping factor? Why does the surfer sometimes jump to a random page?"}},{"node":"eigen","ask":{"zh":"幂迭代怎样算出这个长期概率？它和特征向量有什么关系？","en":"How does power iteration compute that long-run probability? What does it have to do with an eigenvector?"}}],"reveal":{"zh":"重要不只看链接数，还看链接来自谁；随机冲浪者的长期停留概率就是 PageRank，幂迭代算出的正是它的特征向量。","en":"Importance is not just link count but who links to you; the random surfer's long-run stay probability is PageRank, and power iteration computes exactly its eigenvector."},"source":"../pagerank/#step2","lesson":"pagerank","stage":"university","group":"math"},
    {"id":"q-photoelectric-effect-0","question":{"zh":"为什么光再亮也打不出电子？","en":"Why can bright light still fail to free electrons?"},"chain":["spectrum","photoelectric-effect","interference"],"target":{"node":"photoelectric-effect","href":"../photoelectric-effect/#step1"},"prompts":[{"node":"spectrum","ask":{"zh":"光子能量由频率决定——光再亮，亮的是什么？单个光子的能量变了吗？","en":"A photon's energy is set by frequency — when light gets brighter, what actually brightens? Does a single photon's energy change?"}},{"node":"photoelectric-effect","ask":{"zh":"逸出功和截止频率是什么关系？频率低于截止频率时，再多光子有用吗？","en":"How do work function and threshold frequency relate? Below the threshold frequency, do more photons help?"}},{"node":"interference","ask":{"zh":"遏止电压测出的是什么？怎样用它测出 h？","en":"What does the stopping voltage measure? How can it measure h?"}}],"reveal":{"zh":"打出电子靠单个光子的能量 hν，不是总亮度；频率低于截止频率，单个光子能量不够，逸出功跨不过，再亮也打不出。","en":"Freeing an electron takes a single photon's energy hν, not total brightness; below the threshold frequency each photon is too weak to clear the work function, no matter how bright the light."},"source":"../photoelectric-effect/#step1","lesson":"photoelectric-effect","stage":"university","group":"waves"},
    {"id":"q-poisson-process-0","question":{"zh":"随机到达的事件有什么规律？","en":"What regularities do random arrivals have?"},"chain":["probability","poisson-process","montecarlo"],"target":{"node":"poisson-process","href":"../poisson-process/#step2"},"prompts":[{"node":"probability","ask":{"zh":"恒定平均速率下随机到达——间隔服从什么分布？窗口内个数服从什么分布？","en":"Random arrivals at a constant average rate — what distribution do the gaps follow? The counts per window?"}},{"node":"poisson-process","ask":{"zh":"指数分布无记忆是什么意思？已经等了很久，下一个到达会更快来吗？","en":"What does the exponential distribution's memorylessness mean? After a long wait, does the next arrival come sooner?"}},{"node":"montecarlo","ask":{"zh":"独立泊松流合并与稀释后仍是泊松——模拟很多次，散度比能判断一组数据像不像泊松吗？","en":"Independent Poisson streams stay Poisson when merged or thinned — over many simulations, can the dispersion ratio judge whether data look Poisson?"}}],"reveal":{"zh":"间隔指数分布、个数泊松分布，指数分布无记忆——等多久都不影响下一次；合并与稀释后仍是泊松，散度比可以检验数据像不像泊松。","en":"Gaps are exponential, counts are Poisson, and exponential means memoryless — waiting longer changes nothing about the next arrival; merging and thinning stay Poisson, and the dispersion ratio tests whether data look Poisson."},"source":"../poisson-process/#step2","lesson":"poisson-process","stage":"university","group":"measurement"},
    {"id":"q-prisoners-dilemma-0","question":{"zh":"为什么合作能在自私者中存活？","en":"How can cooperation survive among selfish players?"},"chain":["game-theory","prisoners-dilemma","natural-selection"],"target":{"node":"prisoners-dilemma","href":"../prisoners-dilemma/#step3"},"prompts":[{"node":"game-theory","ask":{"zh":"一次博弈里背叛为什么占优？占优策略需要知道对手会怎么做吗？","en":"Why does defection dominate a single round? Does a dominant strategy need to know what the opponent will do?"}},{"node":"prisoners-dilemma","ask":{"zh":"重复博弈和继续概率阈值 δ* 怎样改变结论？噪声下宽容为什么有价值？","en":"How do repeated play and the continuation threshold δ* change the conclusion? Why is forgiveness valuable under noise?"}},{"node":"natural-selection","ask":{"zh":"得分怎样决定谁被复制？三策略复制者动态里，合作者靠什么翻盘？","en":"How does score decide who gets copied? In three-strategy replicator dynamics, what lets cooperators turn the tables?"}}],"reveal":{"zh":"一次博弈中背叛占优，但重复博弈、循环赛与继续概率阈值 δ* 让合作有了未来收益。三策略复制者动态里，得分决定谁被复制，噪声下宽容的策略反而活得更久。","en":"Defection dominates a single round, but repeated play, round-robins and the continuation threshold δ* give cooperation future payoffs. In three-strategy replicator dynamics score decides who is copied, and forgiving strategies last longer under noise."},"source":"../prisoners-dilemma/#step3","lesson":"prisoners-dilemma","stage":"university","group":"systems"},
    {"id":"q-quantum-tunneling-0","question":{"zh":"粒子没有足够能量，为什么还能穿过去？","en":"Why can a particle pass without enough energy?"},"chain":["interference","quantum-tunneling"],"target":{"node":"quantum-tunneling","href":"../quantum-tunneling/#step1"},"prompts":[{"node":"interference","ask":{"zh":"稳态波函数在势垒内指数衰减——衰减到零了吗？墙后还剩多少？","en":"A steady wave function decays exponentially inside a barrier — does it reach zero? How much remains past the wall?"}},{"node":"quantum-tunneling","ask":{"zh":"透射概率随墙宽指数下降——墙加厚一倍，透射概率是减半还是指数式暴跌？","en":"Transmission falls exponentially with wall width — double the wall, and does transmission halve or crash exponentially?"}}],"reveal":{"zh":"波函数在墙内指数衰减但不到零，墙后留有透射份额；墙越宽、粒子越重，透射概率指数式越小，扫描隧道显微镜正是用这指数灵敏度成像。","en":"The wave function decays exponentially inside the wall but never reaches zero, leaving a transmitted share; wider walls and heavier particles shrink transmission exponentially, and the scanning tunnelling microscope images with exactly that exponential sensitivity."},"source":"../quantum-tunneling/#step1","lesson":"quantum-tunneling","stage":"university","group":"waves"},
    {"id":"q-recursion-divide-0","question":{"zh":"为什么有的递归瞬间完成，有的永远算不完？","en":"Why do some recursions finish instantly and others never finish?"},"chain":["recursion-divide","binary-search","exp-log"],"target":{"node":"recursion-divide","href":"../recursion-divide/#step2"},"prompts":[{"node":"recursion-divide","ask":{"zh":"规模怎样缩小、每层做多少事，怎样共同决定总代价？归并排序的分而治之长什么样？","en":"How do shrinking size and per-level work together set the total cost? What does merge sort's divide-and-conquer look like?"}},{"node":"binary-search","ask":{"zh":"每次对半砍时，规模缩小得有多快？为什么有序是前提？","en":"When you halve the range each time, how fast does the size shrink? Why is sorted order a precondition?"}},{"node":"exp-log","ask":{"zh":"汉诺塔的步数为什么按指数长？对数和“砍几次”有什么关系？","en":"Why does the Tower of Hanoi's step count grow exponentially? What does a logarithm have to do with “how many halvings”?"}}],"reveal":{"zh":"递归的总代价由规模缩小速度和每层工作量共同决定：二分查找每次对半砍、步数按对数长，所以瞬间完成。汉诺塔每层翻倍、步数按指数长，规模稍大就永远算不完。","en":"A recursion's total cost is set by how fast the size shrinks and how much each level does: binary search halves each time so its steps grow logarithmically and it finishes instantly. The Tower of Hanoi doubles each level so its steps grow exponentially, and a slightly bigger size never finishes."},"source":"../recursion-divide/#step2","lesson":"recursion-divide","stage":"university","group":"systems"},
    {"id":"q-relativity-0","question":{"zh":"为什么光速不能被超过？","en":"Why can’t the speed of light be exceeded?"},"chain":["net-force","relativity"],"target":{"node":"relativity","href":"../relativity/#step1"},"prompts":[{"node":"net-force","ask":{"zh":"光速不变出发——光钟的时间膨胀说明什么？运动的钟变快还是变慢？","en":"Starting from a constant speed of light — what does a light clock's time dilation show? Does a moving clock run fast or slow?"}},{"node":"relativity","ask":{"zh":"同时性的相对性是什么意思？两个惯性观察者对“同时”会达成一致吗？","en":"What does the relativity of simultaneity mean? Will two inertial observers agree on what is “simultaneous”?"}}],"reveal":{"zh":"光速不变推出时间膨胀、同时相对；有质量粒子越近光速，动能发散到无穷，所以永远到不了光速。","en":"A constant speed of light forces time dilation and relative simultaneity; a massive particle's kinetic energy diverges as it nears light speed, so it can never reach it."},"source":"../relativity/#step1","lesson":"relativity","stage":"university","group":"waves"},
    {"id":"q-risk-pooling-0","question":{"zh":"为什么保险靠人多才算得准？","en":"Why does insurance only work with many people?"},"chain":["variance","risk-pooling","gaussian"],"target":{"node":"risk-pooling","href":"../risk-pooling/#step1"},"prompts":[{"node":"variance","ask":{"zh":"一个人 0 或 10000 元的赌局——人均损失的波动随人数怎样变？按 1/√N 缩小是什么意思？","en":"One person's $0-or-$10,000 gamble — how does the spread of average loss change with pool size? What does shrinking as 1/√N mean?"}},{"node":"risk-pooling","ask":{"zh":"人数多了，保费为什么能算准？破产概率怎样变？","en":"With more people, why can the premium be priced accurately? What happens to the ruin probability?"}},{"node":"gaussian","ask":{"zh":"共同灾难使波动停在下限——为什么人再多也没用？逆向选择又怎样让保费螺旋上升？","en":"A shared catastrophe floors the spread — why doesn't adding people help? And how does adverse selection spiral premiums upward?"}}],"reveal":{"zh":"人均损失波动按 1/√N 缩小，人越多保费越可算；但共同灾难让风险无法分散、逆向选择推高保费，保险的边界就在这里。","en":"Average-loss spread shrinks as 1/√N, so bigger pools price more accurately; but shared catastrophes cannot be diversified away and adverse selection pushes premiums up — those are insurance's boundaries."},"source":"../risk-pooling/#step1","lesson":"risk-pooling","stage":"university","group":"measurement"},
    {"id":"q-rsa-encryption-0","question":{"zh":"为什么公开的锁不会泄露钥匙？","en":"Why doesn’t a public lock leak the key?"},"chain":["exp-log","rsa-encryption","hashing"],"target":{"node":"rsa-encryption","href":"../rsa-encryption/#step3"},"prompts":[{"node":"exp-log","ask":{"zh":"位数每加 1，试除的步数为什么乘 10？指数增长在这里意味着什么？","en":"Why does one more digit multiply trial-division work by ten? What does exponential growth mean here?"}},{"node":"rsa-encryption","ask":{"zh":"质数相乘易、分解难，怎样变成公钥和私钥？欧拉定理在其中起什么作用？","en":"How does “multiplying primes is easy, factoring is hard” become a public and a private key? What role does Euler's theorem play?"}},{"node":"hashing","ask":{"zh":"单向函数是什么意思？为什么哈希和 RSA 都依赖它？","en":"What is a one-way function? Why do both hashing and RSA rely on one?"}}],"reveal":{"zh":"质数相乘易、分解难，模算术、欧拉定理与扩展欧几里得算法造出公钥和私钥，加密解密对所有明文成立。窃听者只能试除，而位数每加 1 步数乘 10，现实密钥长度让试除不可行。","en":"Multiplying primes is easy and factoring is hard, so modular arithmetic, Euler's theorem and the extended Euclidean algorithm build a public and a private key for which encryption and decryption hold for every message. An eavesdropper can only trial-divide, and one more digit means ten times the work, so real key lengths make it infeasible."},"source":"../rsa-encryption/#step3","lesson":"rsa-encryption","stage":"university","group":"math"},
    {"id":"q-shortest-path-0","question":{"zh":"地图软件怎样找最短路线？","en":"How does a map app find the shortest route?"},"chain":["graph-algorithms","shortest-path","pagerank"],"target":{"node":"shortest-path","href":"../shortest-path/#step1"},"prompts":[{"node":"graph-algorithms","ask":{"zh":"图上的算法一般先定义什么（点、边、代价）？为什么“按顺序展开”是个通用想法？","en":"What does a graph algorithm usually define first (vertices, edges, costs)? Why is “expanding in order” a general idea?"}},{"node":"shortest-path","ask":{"zh":"迪杰斯特拉每次确认暂定距离最小的点，为什么这样能保证最短？负权为什么会让它出错？","en":"Why does settling the smallest tentative distance each time guarantee the shortest path? Why do negative weights break it?"}},{"node":"pagerank","ask":{"zh":"同样在图上累积一个量，PageRank 和最短路累积的东西有什么不同？","en":"PageRank also accumulates a quantity over a graph — how does what it accumulates differ from a shortest path?"}}],"reveal":{"zh":"带权图里路径代价是权重之和，迪杰斯特拉每次确认暂定距离最小的点、像洪水从起点漫开。负权会让它出错，网格地图上泥地代价决定穿过还是绕开，A* 用启发值少确认一些格。","en":"In a weighted graph a path's cost is the sum of weights, and Dijkstra settles the smallest tentative distance each time, like a flood from the start. Negative weights make it fail, mud costs on a grid decide crossing versus detouring, and A* uses a heuristic to settle fewer cells."},"source":"../shortest-path/#step1","lesson":"shortest-path","stage":"university","group":"systems"},
    {"id":"q-taylor-series-0","question":{"zh":"为什么复杂的函数能被多项式代替？","en":"Why can a complicated function be replaced by a polynomial?"},"chain":["derivative","taylor-series","fourier"],"target":{"node":"taylor-series","href":"../taylor-series/#step2"},"prompts":[{"node":"derivative","ask":{"zh":"系数来自各阶导数——在一点处让多项式和函数各阶导数都相等，近处会贴合吗？","en":"Coefficients come from derivatives of each order — matching a polynomial's derivatives to the function's at one point: does it fit nearby?"}},{"node":"taylor-series","ask":{"zh":"收敛半径内加项变准、半径外越加越差——对 ln(1+x)，半径是多少？","en":"Inside the radius of convergence more terms mean more accuracy, outside it worse — for ln(1+x), what is the radius?"}},{"node":"fourier","ask":{"zh":"泰勒是局部逼近，傅里叶是整体逼近——两者各适合什么场景？","en":"Taylor approximates locally, Fourier globally — which scenes suit each?"}}],"reveal":{"zh":"在一点处逐项贴合各阶导数，近处多项式就和函数几乎重合；收敛半径内加项变准，半径外反而变差；傅里叶则是用正弦波在整体上逼近。","en":"Matching derivatives term by term at one point makes the polynomial nearly coincide nearby; inside the radius more terms help, outside they hurt; Fourier instead approximates globally with sine waves."},"source":"../taylor-series/#step2","lesson":"taylor-series","stage":"university","group":"math"},
    {"id":"q-wavelets-0","question":{"zh":"频率什么时候出现？","en":"When does a frequency occur?"},"chain":["fourier","spectrum","wavelets"],"target":{"node":"wavelets","href":"../wavelets/#step2"},"prompts":[{"node":"fourier","ask":{"zh":"傅里叶幅度谱说明有哪些频率——它告诉你频率出现的先后吗？","en":"A Fourier magnitude spectrum shows which frequencies are present — does it say when each occurs?"}},{"node":"spectrum","ask":{"zh":"加窗后分析怎样同时定位时间与频率？窗口窄了，时间定位和频率定位各怎样变？","en":"How does windowing locate time and frequency together? With a narrower window, how do time and frequency localisation each change?"}},{"node":"wavelets","ask":{"zh":"小波和加窗傅里叶有什么不同？Morlet 小波为什么适合这件事？","en":"How do wavelets differ from windowed Fourier? Why is the Morlet wavelet suited to this?"}}],"reveal":{"zh":"傅里叶谱只说有哪些频率、不说何时出现；加窗和小波把信号切成时段再分析频率，时间与频率就同时定位了。","en":"A Fourier spectrum lists frequencies but not their timing; windowing and wavelets slice the signal into time spans before analysing frequency, locating time and frequency together."},"source":"../wavelets/#step2","lesson":"wavelets","stage":"university","group":"waves"},
  ];
})();
